window.__AI4S_API__.articleDetails=Object.assign(window.__AI4S_API__.articleDetails||{},{"report-policy-toolkit":{"id":46,"slug":"report-policy-toolkit","title":"从规划到抓手：十五五开局 AI 科研政策工具箱的四件套","kind":"report","dek":"上一期《规划即生产力》讲国家为 AI 科研\"规划了什么\"，本期回答\"怎么落地\"。10月上旬，中央文件、省级三张补贴券、国家级语料联盟、全产业链评测基准四件套接连落子，从顶层设计、资金、数据、评测四个环节，把政策变成高校能摸到的工具。本报告拆解这套工具箱，并附信息中心与科研管理人员可直接套用的行动清单。","tags":["政策工具箱","补贴券","语料标准","评测基准","科研范式变革","高校信息中心"],"sources":[{"url":"https://finance.sina.cn/china/gncj/2026-10-09/detail-iniurmnf2915905.d.html","site":"新浪财经","title":"中共中央、国务院印发《关于发展新质生产力的意见》","date":"2026-10-09"},{"url":"https://finance.sina.cn/2026-10-09/detail-iniurvzz2751116.d.html","site":"新浪财经（上海证券报）","title":"江苏推出AI专项补贴券 最高可获500万元扶持","date":"2026-10-09"},{"url":"https://finance.sina.cn/2026-10-09/detail-iniurruh1034429.d.html","site":"新浪财经","title":"江苏官宣推出词元（Token）券，最高补贴500万元","date":"2026-10-09"},{"url":"https://finance.sina.cn/2026-10-11/detail-iniuvanp1893313.d.html","site":"新浪财经（新华日报）","title":"三张补贴券为AI研发\"精准加油\"","date":"2026-10-11"},{"url":"https://news.sciencenet.cn/htmlnews/2026/9/572309.shtm","site":"科学网","title":"全国性语料创新生态联盟在京启动","date":"2026-09-29"},{"url":"https://www.chinanews.com.cn/gn/2026/09-29/10705846.shtml","site":"中国新闻网","title":"全国性语料创新生态联盟在北京启动 集中发布系列重要成果","date":"2026-09-29"},{"url":"https://news.bjd.com.cn/2026/10/13/11993702.shtml","site":"京报网（央视新闻客户端）","title":"\"求索\"4.0上线！国内首个人工智能全产业链评测基准发布","date":"2026-10-13"},{"url":"https://news.sina.cn/znl/2026-09-01/detail-iniqhwmx8268522.d.html","site":"新浪网","title":"人工智能如何引领科研范式变革","date":"2026-09-01"},{"url":"https://k.sina.cn/article_5952915720_162d2490806704z5as.html?from=tech","site":"新浪科技","title":"科技观察｜科研需要AI，AI需要什么"},{"url":"https://finance.eastmoney.com/a/202511193568887697.html","site":"东方财富网（人民网）","title":"信息技术国际标准化高级别研讨会举办","date":"2025-11-19"}],"region":"中国大陆","layers":["区域公共基础设施","数据与语料","工具链与智能体"],"issue_no":null,"pinned":false,"word_count":4197,"published_at":"2026-10-15T02:57:35.580071+00:00","body_md":"## 一、顶层设计：中央文件把\"科研范式变革\"写进新质生产力十九项举措\n\n10月9日，中共中央、国务院印发《关于发展新质生产力的意见》，部署十九项重点举措。其中明确要求\"以人工智能引领科研范式变革，助力提升科研效率\"，提出强化算力、算法、数据高效供给，全面实施\"人工智能+\"行动，布局国家人工智能行业应用中试基地。\n\n这不是孤立的表态，而是一条连续三年的政策传导链。2025年8月，国务院发布《关于深入实施\"人工智能+\"行动的意见》，把\"人工智能+\"科学技术列为重点行动之一，提出\"加快探索人工智能驱动的新型科研范式\"。2025年10月，十五五规划建议提出\"以人工智能引领科研范式变革，加强人工智能同产业发展、文化建设、民生保障、社会治理相结合\"。如今中央文件把这句话正式写进十九项重点举措，从\"规划建议\"走到\"中央意见\"，政策传导的链条已经走完。\n\n为什么这条链条对高校特别重要？有学者点出了四个现实短板：科研场景的算力供给不足且分布不均衡，智能化算力共享体系尚未建立；统一的数据标准与开放共享机制仍未形成，跨机构数据壁垒突出；科研组织形式滞后于跨机构、跨学科联合攻关的需求；传统的科研资助、评价和组织方式难以满足开放开源需求。换句话说，政策层已经把\"范式变革\"定为方向，但高校信息中心和科研管理部门面对的是\"钱在哪、数据在哪、怎么验收\"的具体问题——这正是接下来三章要讲的工具箱。\n\n小结：顶层设计已经从\"鼓励探索\"进入\"部署举措\"阶段，接下来比拼的是谁能把政策翻译成可申报的项目、可调用的资源。\n\n## 二、钱：江苏三张补贴券，补贴从\"买卡\"转向\"买词元\"\n\n10月9日，江苏省发展改革委、财政厅、数据局等五部门联合印发《江苏省支持人工智能创新发展有关实施方案》，推出词元（Token）券、语料券、模型券三张 AI 补贴券。\n\n词元券针对的是最实在的成本：在江苏注册经营的企业、高校院所、科研机构及一人智能体公司（OPC），购买智能算力服务（含智能算力租赁）进行模型训练、推理、智能体应用等，均可申领。省市支持总额原则上不超过实际支付费用的百分之五十，单家主体上限五百万元；省级财政承担各地兑付总额的百分之五十，地市配套。申领门槛：算力采购支出不少于一万元，调用的大模型须完成国家网信办生成式 AI 备案，采购方与算力供给方无关联，信用良好且近三年无重大违法违规记录。政策覆盖 2026年7月1日（含）之后签订的合同，有效期至 2027年6月30日，依托江苏省一体化算力监测调度平台线上申报。\n\n语料券针对数据成本：购买和建设高质量数据集及行业语料资源，省市支持总额原则上不超过实际支付费用的百分之五十，单家主体上限一百万元。省级财政还对列入国家级高质量数据集建设先行先试的项目给予五十万元一次性支持，对省级优秀项目给予二十万元一次性支持。对具身智能机器人数据采集，省级财政按在省数据交易所达成或备案的产品实际交易结算金额的百分之三十给予支持，同一申报主体累计上限二百万元。\n\n模型券针对自研模型：对拥有经国家网信办备案的生成式人工智能服务的省内主体，按实际研发投入支出的百分之三十予以支持，最高一百万元，实行总量控制、按综合得分排序兑付。\n\n这套机制有试点基础：扬州此前已先行试点市级词元券，本次是把试点经验全省推广。横向看，各地都在往同一方向走：成都每年发放词元券总额不超过一亿元，单家主体不超过实际购买金额的百分之三十（小微企业不超过百分之五十）、最高二百万元；武汉江岸区计划每年发放一千万元 Token 券；南昌红谷滩区年度设置六百万元额度。补贴正在从补服务器、GPU 等重资产投入，转向补贴模型调用和词元消耗等持续运营成本。\n\n分析：这对高校信息中心意味着，校级智算平台的算力调用、教师调用大模型 API 的词元开支，第一次有了\"据实兑付\"的财政通道——按实际调用量补助，更贴合大模型按量计费的商业模式。高校院所是明确列出的申领对象，信息中心统一采购、统一结算的账，天然符合\"算力采购支出不少于一万元\"这类门槛。\n\n小结：钱的工具已经从\"立项给设备\"变成\"用多少补多少\"。对江苏的高校，这是一张有效期到 2027 年中、有明确申报入口的政策单；对其他省份，这套模式是跟本地发改委、数据局沟通补贴依据的现成参照。\n\n## 三、数据：语料创新生态联盟，把国家级语料库变成公共基础设施\n\n9月29日，由中国科学院文献情报中心发起、以\"共建语料生态·共创智能未来\"为主题的\"语料创新生态联盟启动暨学术交流会\"在北京举行，全国性语料创新生态联盟正式启动，并集中发布语料标准规范、敖仓·语料社区服务平台及英文期刊《人工智能语料研究》（Data Express in AI Corpus）等系列成果。\n\n背景要先看清：2026年7月的世界人工智能大会上，由中国科学院牵头建设的国家级敖仓·科技语料库对外发布，目标是突破 AI4S 语料供给瓶颈、夯实人工智能数据基座。两个多月后，联盟落地，把语料库变成生态。\n\n启动会上发布的五类四十二项科技语料标准，围绕科技语料建设、工具平台、业务流程和运营管理等环节。按计划先行先用、逐步上升为行业标准和国家标准。联盟首批五十家共建单位覆盖国家实验室、科研院所与国家级科学数据与文献资源机构，地方政府，以及人工智能、数据基础设施、出版与知识服务等领域骨干单位，语料运营企业和人工智能领域知名投资机构，贯通语料资源供给、技术研发、平台建设、模型训练与行业应用全链条。\n\n联盟发起人、中国工程院院士孙凝晖提出，联盟要推动科技语料资源和加工能力的基础设施化，建设国家高质量科技语料资源的战略保障基地、国家智能就绪语料集成服务的协同枢纽。中国科学院文献情报中心主任曲建升介绍了下一步的五大任务：联合共建高质量科技语料；推进智能就绪科技语料集成服务，探索开放、普惠的公共服务机制；深化国家科技语料基础设施协同建设；强化标准、质量与可信治理；开展 AI4S 模型与应用场景联合验证。会上，文献情报中心还代表敖仓·科技语料库，分别与语料应用关键机构、国家人工智能应用中试基地签署合作协议。\n\n分析：语料供给正在从\"各家找数据\"变成\"国家级公共服务\"。对高校有三层意义：数据采购合规化——四十二项标准先行先用，高校购买、加工语料有了可参照的国家队规范；成本可叠加——语料券补贴\"高质量数据集采购与数据标注开支\"，和联盟服务形成\"国家出平台、地方补采购\"的组合；应用有出口——联盟要做 AI4S 模型与应用场景联合验证，高校科研任务可以直接变成验证场景。\n\n小结：数据环节的工具是\"标准+平台+联盟\"。科研管理人员可以把本校有学科特色的语料资源（如生物医学、材料科学数据）对接到联盟的共建体系里，既是贡献也是获取反哺服务的入口。\n\n## 四、评测：求索 4.0，给采购和选型一把统一标尺\n\n10月13日，中国电子技术标准化研究院发布国内首个面向算力、模型算法、智能系统与产品、行业应用、安全治理等人工智能全产业链的评测基准——\"求索\"4.0版。\n\n这套体系的核心价值是\"可比\"。它为芯片、模型等厂商提供了统一的测试流程和评测标尺，还配套电力、医疗、钢铁等真实的业务测试负载，消除不同环境下评测结果不可比的行业痛点。整套体系分为基础软硬件、模型与智能系统、安全治理、行业落地四大板块，十六项测评工具，覆盖从底层算力、软硬件协同、智算云、智能软件工程，到大模型、智能体、具身智能、智能终端、AI 安全、行业场景的全面测评。\n\n对高校最友好的一点是开放。中国电子技术标准化研究院信息技术中心模型与应用创新研究室主任鲍薇表示，\"求索\"算力、大模型、智能体等轻量版代码工具对外开源，方便产业快速复现评测、开展软硬件协同验证，把抽象的评测分数转化为真实选型的依据。而在此之前，\"求索\"已经面向产业链开展多轮试点测评，在金融、电力、石油石化等场景完成产品验证，积累了多项行业落地实践案例。\n\n还有一个容易被忽略的国际维度：2025年11月15日，在成都举办的信息技术国际标准化高级别研讨会上，\"求索\"人工智能国家标准评测基准体系国际版已发布，包含人工智能系统性能基准、大模型评测基准、人工智能软硬件适配测试工具、人工智能芯片性能测试基准、存储性能测试基准、大模型安全测试评估工具、人工智能生成合成内容标识与检测工具等，面向全球厂商和行业用户。\n\n分析：评测基准解决的是信息中心最头疼的问题——厂商 PPT 里的分数没法横向比较。有了国家标准评测基准，招标和验收指标可以直接引用\"求索\"测评项；轻量版开源意味着实验室自己就能复跑，不必完全依赖厂商自测。这意味着，高校的大模型选型和智算平台验收，第一次有了不被厂商绑定的第三方标尺。\n\n小结：评测环节的工具是\"统一标尺+开源复现+真实负载\"。下一次做大模型采购或智算平台验收，把\"求索\"测评项写进技术规格书，是成本最低的抓手。\n\n## 五、四件套的咬合逻辑：顶层设计、资金、数据、评测第一次同向发力\n\n把四件事放在一起看，一条清晰的传导链出现了：\n\n中央文件给出方向——\"以人工智能引领科研范式变革\"，强化算力、算法、数据高效供给，全面实施\"人工智能+\"行动，布局国家人工智能行业应用中试基地；江苏三券给出钱——按实际调用量据实补助，把财政资金变成高校能申报的运营补贴；语料联盟给出\"粮\"——国家级语料库、五类四十二项标准、开放普惠的集成服务，解决\"AI 需要什么\"的供给侧问题；求索 4.0 给出\"尺\"——统一的评测标尺和可复现的开源工具，让采购和验收有据可依。\n\n更值得注意的是咬合点。中央文件部署的\"国家人工智能行业应用中试基地\"，和语料联盟启动会上与\"国家人工智能应用中试基地\"签署的合作协议，是同一件事的上下游：中试基地是场景和验证场，语料联盟是数据供给方。江苏的语料券明确支持\"高质量数据集采购与数据标注开支\"，而联盟的敖仓·语料社区服务平台正是这类采购可以对接的国家队供给。钱、数据、场景，在这里形成闭环。\n\n小结：四件套的实质，是把\"AI 引领科研范式变革\"这句顶层表述，拆解成了信息中心主任能申报、科研管理人员能对接、采购部门能引用的具体工具。\n\n## 六、行动清单：高校信息中心与科研管理部门可以现在做的六件事\n\n第一，算一笔\"词元账\"。梳理本校大模型 API 调用量和智算平台算力租赁支出，2026年7月1日之后签订的合同都在江苏三券覆盖范围内（江苏高校直接申报，其他省份参照成都、武汉、南昌模式与本地发改委、数据局沟通）。有效期到 2027年6月30日，时间窗口明确。\n\n第二，把数据采购对接到国家队。关注语料创新生态联盟发布的五类四十二项科技语料标准和敖仓·语料社区服务平台，高校采购高质量数据集时优先选择符合联盟规范的供给方；有学科特色语料资源的院系，可以申请成为联盟共建单位，把\"数据贡献\"变成\"能力反哺\"。\n\n第三，选型和验收引用求索基准。下一次大模型采购、智算平台扩容或验收，在技术规格书里直接引用\"求索\"4.0 的测评项，并要求厂商提供可复现的测评报告；实验室层面可以直接用开源的轻量版代码工具做横向对比。\n\n第四，对接\"人工智能+\"行动和中试基地。中央文件明确\"全面实施'人工智能+'行动，布局国家人工智能行业应用中试基地\"，语料联盟已经与中试基地签约。有行业应用场景的高校（如医疗、能源、制造交叉学科），可以主动对接中试基地的联合验证任务，把科研项目变成国家级验证场景。\n\n第五，自研垂类模型走\"模型券\"逻辑。江苏的模型券要求主体拥有经国家网信办备案的生成式 AI 服务、按实际研发投入的百分之三十支持。这给有自研学科大模型的高校指了一条路：先完成网信办备案，再谈补贴和推广。\n\n第六，组织上设一个\"政策-申报\"对口岗。三券的申报入口在江苏省一体化算力监测调度平台，需要合同、发票、付款凭证、词元计量材料；语料联盟的对接在中科院文献情报中心；求索的测评在电子标准院。三个入口分属不同部门，信息中心牵头设一个对口岗，比各自为战效率高得多。\n\n政策工具箱的出现，意味着高校 AI for Science 的竞争维度正在变化——过去比谁先买到卡、谁先搭起平台，接下来比谁能把政策工具用足：补贴申报的速度、语料标准的跟进、评测基准的引用。这三件事都不需要新增预算，需要的是信息。"},"report-quantum-campus":{"id":49,"slug":"report-quantum-campus","title":"量子进校园：当量子计算机成为高校\"新基建\"","kind":"report","dek":"此前谈经典超算，这篇看量子算力：10月 IonQ 把 256 比特量子计算机搬进剑桥，建首个大学驻点量子中心；美能源部 12 个二期项目 1.59 亿美元点名量子纠错；阿肯色大学拿 NSF 340 万美元建量子材料机器人实验室。拆解三条路径，附行动清单。","tags":["量子计算","高校基础设施","产学合作","科研算力","人才培养"],"sources":[{"url":"https://ionq.com/news/ionq-and-the-university-of-cambridge-open-the-ionq-quantum-innovation-centre-at-cavendish-laboratorys-ray-dolby-centre","site":"IonQ 官网","title":"IonQ and the University of Cambridge Open the IonQ Quantum Innovation Centre at Cavendish Laboratory's Ray Dolby Centre","date":"2026-10-15"},{"url":"https://www.businesswire.com/news/home/20261015515775/en/IonQ-and-the-University-of-Cambridge-Open-the-IonQ-Quantum-Innovation-Centre-at-Cavendish-Laboratorys-Ray-Dolby-Centre","site":"Business Wire","title":"IonQ and the University of Cambridge Open the IonQ Quantum Innovation Centre at Cavendish Laboratory's Ray Dolby Centre","date":"2026-10-15"},{"url":"https://www.ad-hoc-news.de/boerse/unternehmensnachrichten/ionq-opens-cambridge-lab-as-wall-street-trims-price-targets-on-dilution/70334197","site":"ad-hoc-news.de","title":"IonQ Opens Cambridge Lab as Wall Street Trims Price Targets on Dilution and Commercial Doubts","date":"2026-10-16"},{"url":"https://www.bnl.gov/newsroom/news.php?a=223204","site":"布鲁克海文国家实验室（美国能源部）","title":"Energy Department Announces New Genesis Mission Awards to Advance Super Intelligence for Science","date":"2026-10-08"},{"url":"https://thequantuminsider.com/2026/10/08/energy-department-announces-new-genesis-mission-awards-to-accelerate-scientific-capability/","site":"The Quantum Insider","title":"Energy Department Announces New Genesis Mission Awards to Accelerate Scientific Capability","date":"2026-10-08"},{"url":"https://fedscoop.com/genesis-mission-investment-nvidia-google-anthropic-openai/","site":"FedScoop","title":"Genesis Mission investment: NVIDIA, Google, Anthropic, OpenAI commit funds","date":"2026-10-08"},{"url":"https://www.anthropic.com/news/genesis-mission-commitment","site":"Anthropic 官网","title":"Anthropic commits $150M to the Genesis Mission","date":"2026-10-08"},{"url":"https://theaijournal.co/2026/10/us-energy-department-super-intelligence-projects/","site":"The AI Journal","title":"US Energy Department Super-Intelligence Projects: $159M","date":"2026-10-14"},{"url":"https://www.dollarstockclub.com/2026/10/13/nvidia-is-inside-the-does-2-4-billion-science-push-most-others-are-not/","site":"Dollar Stock Club","title":"NVIDIA Is Inside the DOE's $2.4 Billion Science Push","date":"2026-10-13"},{"url":"https://news.uark.edu/articles/83006","site":"阿肯色大学新闻网","title":"Robots and AI Could Speed Search for Quantum Materials","date":"2026-10-13"},{"url":"https://talkbusiness.net/2026/08/university-of-arkansas-establishes-materials-research-institute/","site":"Talk Business","title":"University of Arkansas establishes materials research institute","date":"2026-08-17"},{"url":"https://k.sina.cn/article_5952915720_162d24908067050fmw.html?from=science","site":"上观新闻（新浪）","title":"2026中德物理会议与海科汇德国物理人才专场活动顺利举办","date":"2026-10-17"}],"region":"国内外","layers":["算力底座","组织与人才","区域公共基础设施"],"issue_no":null,"pinned":false,"word_count":3615,"published_at":"2026-10-17T02:59:24.774571+00:00","body_md":"# 量子进校园：当量子计算机成为高校\"新基建\"\n\n此前谈经典超算，这篇看量子算力：10月 IonQ 把 256 比特量子计算机搬进剑桥，建首个大学驻点量子中心；美能源部 12 个二期项目 1.59 亿美元点名量子纠错；阿肯色大学拿 NSF 340 万美元建量子材料机器人实验室。拆解三条路径，附行动清单。\n\n## 一、标志事件：一台量子计算机\"住进\"剑桥\n\n10月15日，IonQ 与剑桥大学宣布，在卡文迪许实验室的 Ray Dolby Centre 开设 IonQ 量子创新中心。据 IonQ 公告，这是全球首个大学驻点量子创新中心：IonQ 将在校园内部署一台 Superion 256 量子比特量子计算机，以及一套纠缠分发量子网络——校园量子网络由 2 个量子网络数据中心和 3 个量子网络节点组成。相关研究还包括量子存储芯片与频率转换技术，校外研究者也可经由 IonQ 云访问其量子计算机。合作首批资助 9 个研究项目，覆盖量子计算、量子网络、量子传感与量子安全，并为剑桥新增学术职位、博士后与博士生名额。作为配套，英国创新署 Innovate UK 将在未来 3 年为该中心提供国家量子计算中心（NQCC）的访问与机时，整个合作对标英国国家量子战略。IonQ 量子平台总裁 Jordan Shapiro 表示，中心把剑桥的研究实力与 IonQ 在网络、传感、安全上的能力结合在了一起。IonQ 还称，其 2025 年已实现 99.99% 的双量子比特门保真度，创下世界纪录。\n\n这意味着量子计算与高校的关系换了模式：过去是\"远端排队买机时\"，现在是\"把机器搬进校园、把团队建在一起\"。对企业而言，高校提供的是最稀缺的两样东西——懂量子的人才和可转化的知识产权，外加国家量子战略的政策背书；对高校而言，企业带来的是单靠科研经费买不起、养不起的整机与工程能力，以及直通产业界的就业出口。高校这边出的价是场地、本地人才供给和国家战略的站台——剑桥案例里，对标英国国家量子战略让合作从商业行为升级为国家能力建设。这笔账两边都算得过来，驻点模式才成立。当然也有冷静的声音：有市场评论指出，中心剪彩与硬件真正安装到位是两回事，研究经费也不等于客户收入，量子计算机的价值不能只从比特数规格上读出来。这提醒高校管理者：谈合作要看交付节奏和验收标准，不只看发布会上的数字。\n\n驻点模式把\"设备、人才、机时、政策背书\"打包进了校园，是量子计算基础设施化的标志性一步，也是高校在谈判桌上新的筹码形态。\n\n## 二、联邦资金的两种姿势：拨款与竞赛\n\n10月8日，美国能源部宣布\"创世纪计划\"（Genesis Mission）第二阶段 12 个新项目，共 1.59 亿美元，方向包括聚变数字孪生、极端环境芯片设计、地热、量子纠错、粒子加速器、酶工程、稀土提取等。能源部把这套计划称为面向科学的\"超智能\"（Super Intelligence）能力建设。其中量子相关有两条线：哈佛大学牵头的\"面向科学计算的应用感知纠错\"，把 AI 与量子硬件结合做纠错；橡树岭国家实验室牵头的量子磁体设计，瞄准的是量子比特的\"底盘\"——磁体性能直接决定量子器件能做到多稳。加上此前已公布的项目，第二阶段总数达到 14 个，计划首年项目总数达 297 个，另有 6 个新增的第一阶段项目。资金之外还有产业配套：白宫同日宣布，11 家产业伙伴向创世纪计划联盟承诺 24 亿美元的工具与算力额度，其中 NVIDIA 10 亿美元、AMD 5 亿美元、OpenAI 2 亿美元、Anthropic 与谷歌各 1.5 亿美元。几乎同时，能源部还推出了\"Quantum Genesis Q 竞赛\"：计划资金高达 2.15 亿美元，采用里程碑制拨款，目标是拿出世界首台\"容错且有科学意义\"的量子计算机——钱按结果分期给，不按计划书一次性给。\n\n这意味着联邦资金在量子赛道上摆出了两种姿势：一种是传统的项目制拨款，把量子纠错这类\"卡脖子\"环节点名立项，保的是方向；另一种是里程碑竞赛，把\"容错量子计算机\"设为终点、按结果付费，保的是结果。对高校科研管理者来说，信号很明确：量子纠错是当前公认的第一瓶颈，AI 辅助纠错（智能纠错解码器）是经费正在砸的方向；同时，竞赛制意味着\"做出东西\"比\"写好本子\"更值钱，工程化团队的权重在上升。产业界 24 亿美元的配套承诺则说明，量子与 AI for Science 已经从政府独唱变成\"政府出题、企业出资源\"的合唱。顺手算一笔：1.59 亿美元分给 12 个项目，单个项目平均 1300 多万美元——这是\"大团队、长周期\"的经费形态，不是小课题能消化的，组队申报是前提。\n\n拨款保方向、竞赛保结果、产业保配套，三条线都指向同一个判断：量子计算正在从论文走向可用系统，经费逻辑也跟着变了。\n\n## 三、上游也在进场：为量子\"找材料\"的机器人实验室\n\n10月13日，阿肯色大学材料研究所宣布获得美国国家科学基金会 340 万美元资助，建设一套\"机器人控制、AI 增强\"的研究基础设施，专门加速可用于改进量子器件的新材料研发。该项目是犹他大学牵头的 4 年期 2000 万美元 AURORA 计划的子项目，由 NSF\"可编程云实验室\"计划资助——这个计划专门支持 AI 驱动、可远程访问的实验室的建设与运行，名字里的\"可编程\"指的就是实验流程可以像代码一样被远程调用和复用。它建立在已有的自动化 MonArk 量子铸造厂（MonArk Quantum Foundry）之上，并把实验能力通过云扩展出去，让全州乃至全国的研究者都能远程做实验。研究所主任 Hugh Churchill 说，费耶特维尔的 MonArk 实验室是 AURORA 的\"试验场\"：新仪器和控制软件先在这里搭建调试，跑顺了再搬进犹他州的生产系统，供全国研究者使用。背景是阿肯色大学 2026 年 8 月刚成立材料研究所，把人工智能、量子材料、能源、生物系统、电子与光子学列为五个重点方向，材料科学与工程项目本硕博贯通，还专设了本科辅修。\n\n这意味着\"量子进高校\"不只是\"用量子计算机\"，还有\"造量子器件\"的上游环节。机器人加 AI 做材料筛选，本质上是把\"试错\"这件事自动化、远程化——云实验室就是科研仪器的\"分时租赁\"，仪器在阿肯色，实验者可以在全国任何地方。对信息中心主任来说，这里有个直接启示：未来的科研基础设施不只是算力机房，还包括这类可远程调度、有数据回流的自动化实验平台，校园网的带宽与稳定性、统一身份认证、实验数据的归档与共享，都会是信息中心的事。现在规划\"科研信息化\"，最好把这类平台预留进架构。\n\n量子计算的上游（材料与器件）同样在高校落地，而且一出生就是\"云化、远程、可共享\"的形态，倒逼信息化规划往前看一步。\n\n## 四、被重新定义的\"网络\"：纠缠分发与量子安全\n\n回到剑桥的合作：IonQ 部署的不只是一台计算机，还有一套纠缠分发量子网络——2 个量子网络数据中心加 3 个量子网络节点，外加量子存储芯片与频率转换技术的研究。说人话：这套网络分发的不是数据包，而是\"量子纠缠\"这种特殊的关联状态，用于量子通信与分布式量子计算；存储芯片和频率转换则是为了让纠缠能在光纤里传得更远、存得更久。而在 10 月中旬的上海，2026 中德物理会议上，固态量子计算等前沿方向出现在主旨报告里，中德顶尖学者同台讨论；配套的人才专场（10 月 12 日至 13 日）有 24 位德国高校与科研机构的教授、博士走进上海科创一线，上海仪创港还正式成为留德中国物理学者学会的中国联络点，把一次性的会变成常态化的桥。\n\n这意味着信息中心的老本行——\"网络\"——正在被量子重新定义。今天规划校园网，明天可能要回答：量子网络节点进不进机房？怎么供电制冷？谁来运维、算谁的预算？更现实的是另一面：量子计算成熟之日，就是现有公钥加密体系承压之时。这意味着信息中心现在就该把\"后量子密码迁移\"排进路线图：第一步先盘点，校内哪些系统依赖传统公钥加密、证书有效期多长、供应商有没有迁移计划；第二步定节奏，按系统重要性分批迁移，近两年证书到期的系统优先纳入后量子方案。等攻击和标准都摆到眼前再动手，就晚了。这笔账越早算越便宜。\n\n量子网络是远期变量，后量子安全是近期功课，两者都落在信息中心主任的职责半径里，前者跟踪、后者动手。建议把后量子盘点列入明年的安全工作计划。\n\n## 五、人才：驻点中心首先是\"蓄水池\"\n\n剑桥合作中明确写了一条：支持新增学术职位、博士后和博士生——设备可以搬，人才必须在当地长出来。值得注意的是，新增职位不只面向物理系，量子网络、传感、安全覆盖了工程与计算机，交叉属性从一开始就写进了编制。阿肯色大学的 AURORA 项目同样把人才培养写进设计：MonArk 实验室既是科研试验场，也是研究生的训练场，该校材料科学与工程本硕博贯通，还有本科辅修做早期引流。而 10 月中旬上海的中德物理会议，把\"人才专场\"与学术会议捆绑：24 位德方学者走进张江机器人谷、AI 魔力社区等科创载体，地方政府现场解读科创政策，科研机构与企业直接对接；上海仪创港成为中国联络点后，这种对接有了常设通道。\n\n这意味着量子竞争首先是人才竞争，而高校最大的比较优势恰恰是\"能批量生产人才\"。企业愿意把整机搬进校园，买的也是这个：驻点中心首先是人才蓄水池，其次才是科研产出。对国内高校科研管理者来说，判断句是：与其等\"量子计算机降价\"，不如先布局\"量子人才供给\"——课程、交叉培养、国际交流通道，这些比设备便宜得多，却是未来谈判设备、争取驻点时的筹码。剑桥拿到的不只是一台机器，而是一整套\"职位加学生加机时\"的组合；这个组合的逻辑，国内高校完全可以学。\n\n设备会折旧，人才不会。量子进校园的真正门票，是人；信息中心和科研管理部门现在就能开始攒这张门票。\n\n## 六、给信息中心主任的四问清单\n\n把本轮的三条线摆在一起：剑桥模式（企业驻点、整机进校园、人才机时打包）、能源部模式（联邦拨款加里程碑竞赛、点名量子纠错、产业 24 亿美元配套）、阿肯色模式（机器人加 AI 找材料、云实验室远程共享）。三条线有一个共同点：量子计算都不再是\"物理系自己的事\"，而是需要算力规划、网络、安全、人才配套一起跟上的系统工程。国内也有对应的热度：中德物理会议上固态量子计算进主旨报告，说明学界与产业界的注意力已经到了。\n\n这意味着信息中心主任需要回答四个问题。第一，量子算力要不要进入学校的中长期算力规划？现在回答\"为时尚早\"可以，但要有复评的时间点，比如每年结合预算季复评一次，而不是无限期搁置。第二，机时从哪来？云上排队、加入区域或国际联盟、争取企业驻点，三条路的成本和可控性完全不同，建议先小成本试用云机时、同时跟踪联盟动态。第三，后量子密码迁移什么时候启动？先做资产盘点，再定路线图，这是本轮唯一建议\"现在动手\"的事。第四，跨学科团队怎么配？量子计算天然横跨物理、材料、计算机、数学，单一学院撑不起来，信息中心可以做那个\"搭台子\"的人。这四个问题都不需要今天就拍板买设备，但需要有人开始跟踪、有人负责回答。建议把四个问题写进下一版信息化规划文本，哪怕每题只有半页——写下来，才有人负责、有人复评。\n\n量子计算进校园，信息中心不是观众。先把四个问题立项、指定负责人、定下复评节奏，就是这一轮最划算的投入——花的是注意力，买的是不掉队。\n"},"report-research-agent":{"id":25,"slug":"report-research-agent","title":"科研智能体进高校：谁能跑通“假设—实验—论文”的全流程编排","kind":"report","dek":"复旦“大圣”以300余个技能包跑通假设—实验—验证闭环，上交大SciMaster六小时比肩资深博士一到三个月工作量，Google Co-Scientist首次在真实实验室一次长出三种单层半导体，国家超算互联网上线400余个科学计算智能体。","tags":["科研智能体","多智能体编排","AI4S","星河启智","SciMaster","Co-Scientist","MCP","智能体评测"],"sources":[{"url":"https://m.jfdaily.com/wx/detail.do?id=1076567","date":"2026-03-05","site":"上观新闻","title":"中国高校加速布局AI for Science，科研智能体引领科研范式变革"},{"url":"https://news.fudan.edu.cn/2026/0414/c3521a148731/page.htm","date":"2026-04-14","site":"复旦大学","title":"科研合伙人“大圣”来也"},{"url":"https://ecas.cas.cn/xxkw/kbcd/201115_149501/ml/xxhcxyyyal/202603/t20260306_5103462.html","date":"2026-03-06","site":"中国科学院网信工作网","title":"我国发布超级科研合伙人“大圣”"},{"url":"https://news.sjtu.edu.cn/mtjj/20260203/219648.html","date":"2026-02-02","site":"上海交通大学新闻学术网","title":"人工智能赋能基础科学 上海交大发布科学基座模型与科研智能体等重磅成果"},{"url":"https://www.sohu.com/a/981593011_120988576","date":"2026-01-30","site":"搜狐网/上证报","title":"上海交大发布通用科研智能体SciMaster与基座模型Innovator"},{"url":"https://finance.sina.com.cn/tech/roll/2026-09-15/doc-inirxhzw3652035.shtml","date":"2026-09-15","site":"新浪科技","title":"零门槛搭建科学计算智能体，国家超算互联网亮相2026算力网发展大会"},{"url":"https://hub.baai.ac.cn/view/57610","date":"2026-09-01","site":"智源社区","title":"Co-Scientist升级：AI走出屏幕，首次在真实实验室「造出」半导体"},{"url":"https://www.mse.tsinghua.edu.cn/info/1063/3854.htm","date":"2026-08-30","site":"清华大学材料学院","title":"清华大学材料科学与工程研究院《材料科学论坛》学术报告：Science Navigator：新一代科研知识库与智能体平台"},{"url":"https://www.sznews.com/news/content/2026-09/11/content_32169598.htm","date":"2026-09-11","site":"深圳新闻网","title":"让AI能“想”会“做”，深圳科研团队提出轻量化“双模型协作”材料创制智能体“材智云脑MatBrain”"},{"url":"http://ecas.cas.cn/xxkw/kbcd/201115_146615/ml/xxhcxyyyal/202501/t20250117_5045346.html","date":"2025-01-17","site":"中国科学院网信工作网","title":"美研究人员推出代理实验室 加速科学发现进程"},{"url":"https://news.sina.cn/ai/2024-11-26/detail-incxkxsh7377908.d.html","date":"2024-11-26","site":"新浪新闻","title":"超越 GPT-4o：开源科研模型 OpenScholar 登场，4500 万篇论文检索增强生成回答"},{"url":"https://t.cj.sina.com.cn/articles/view/6456450127/180d59c4f00102cz06","date":"2026-09-14","site":"新浪财经/人民网","title":"服务长周期科研任务 开源基础大模型“书生-S2”发布"},{"url":"https://cernet.edu.cn/xxh/focus/li_lun_yj/202512/t20251204_2705787.shtml","date":"2025-12-04","site":"中国教育和科研计算机网CERNET","title":"主任谈丨如何建设高校智能体？"},{"url":"https://www.caigou.com.cn/news/2026051516.shtml","date":"2026-05-15","site":"教育装备采购网","title":"上海交大“致远一号”赋能智能体模式 引领高校智能体规模化应用"},{"url":"https://export.shobserver.com/baijiahao/html/953371.html","date":"2025-07-26","site":"上观新闻","title":"从科研智能体到罕见病诊断,上海交大最新发布五项全球领先AI成果"}],"region":"国内外","layers":["tools","model","org"],"issue_no":null,"pinned":false,"word_count":7092,"published_at":"2026-09-16T00:05:02.869+00:00","body_md":"# 科研智能体进高校：谁能跑通\"假设—实验—论文\"的全流程编排\n\n## 一、这一年发生了什么：从文献问答到全流程编排\n\n\"智能体\"与\"大模型\"的区别，在一个科研场景里看得最清楚：大模型能回答\"分子动力学在药物筛选中的典型流程是什么\"，智能体则要自己检索文献、调用计算软件、设计实验、分析结果、写出报告——全程只需要研究者给一个自然语言方向。2024 年以来，这条从\"问答\"到\"编排\"的演进明显提速，而 2025—2026 年国内高校和科研院所开始成建制地进场。\n\n时间线上的几个节点值得记录。**2024 年 8 月**，Transformer 论文作者之一 Llion Jones 创立的 **Sakana AI** 推出 **AI Scientist**，首次把\"提出假设—设计实验—运行实验—写论文—自我评审\"串成流水线；其 **AI Scientist-v2** 生成的论文成为首篇完全由 AI 自主完成并通过同行评审的研讨会论文，被 **ICLR 2025** workshop 收录。**2025 年 1 月 8 日**，**AMD** 与**约翰斯·霍普金斯大学**发布 **Agent Laboratory** 框架，用 PhD、Postdoc、ML 工程师、Professor 四个代理分工完成文献综述、实验设计、代码实现与论文评审，官方报告研究成本下降 **84%**，其中 o1-preview 作为后端产出最佳。**2025 年**，**斯坦福大学** James Zou 团队与 **Chan Zuckerberg Biohub** 的\"虚拟实验室\"（Virtual Lab）登上《自然》：由 PI 智能体、免疫学家与计算生物学家等专家智能体和科学评论员智能体组成的团队，自主设计出 SARS-CoV-2 纳米抗体并经实验表征验证——这为\"跨学科协作稀缺\"的普通课题组提供了一个可复用的组织模板。\n\n2026 年，重心移到国内与真实实验室。**3 月 1 日**，**上海科学智能研究院（上智院）**联合**复旦大学**发布升级版星河启智平台及超级科研合伙人\"大圣\"；**3 月 4 日**，**香港科技大学**主办\"AI for Discovery\"峰会，会上披露了港科大\"AI for Lab\"计划与实验室智能体 AINA。**9 月**，**国家超算互联网**在算力网发展大会上披露其科学计算智能体生态的最新规模，**上海人工智能实验室**发布强化长程科研与智能体能力的\"书生-S2\"，**中国科学院深圳先进技术研究院**在《自然-机器智能》发表轻量化双模型科研智能体 MatBrain。科研智能体从论文里的概念，变成了有平台、有技能库、有评测、有运营模式的基础设施。\n\n## 二、国内样本：四种可辨识的落地路线\n\n### 复旦—上智院：星河启智与\"大圣\"，技能包加群体记忆\n\n2026 年 3 月 1 日，上智院联合复旦大学在徐汇\"模速空间\"发布全面升级的**星河启智科学智能开放平台**，核心载体是超级科研合伙人\"**大圣**\"。据复旦校报与中科院网信工作网的报道，\"大圣\"整合多模态科学大模型、**300 余个专家级科研技能模块（Skills）**与长周期多线程的群体记忆架构，通过双层沟通与分支治理机制隔离模糊指令、避免复杂任务中的路径失序；科学家用自然语言提出任务方向后，\"大圣\"做中心化决策与任务拆解，调度多智能体协同执行，并全程沉淀结构化科研记忆。\n\n效果数据来自上观新闻对 3 月 4 日港科大峰会的报道：复旦\"大圣\"在 RNA 分类与设计任务上准确率达 **96%**，在 siRNA 设计中将实验成功率提升**超 50%**，支撑了转化价值 **2000 万元**的新型补锂剂研发与潜在价值 **5 亿美元**的 FIC 类药物发现。发布会现场还演示了自然语言指令直达上智院生命实验室的实时实验：关键参数自动预填充，实验流程转化为机器可执行代码，设备远程启动。星河启智平台本身于 2025 年 7 月问世，已形成\"数据—模型—算力—实验—智能体—社区\"一体化闭环。\n\n### 上海交大：SciMaster 与基座模型 Innovator，把评测当成基础设施\n\n**上海交通大学**的路线更强调\"基座模型 + 智能体 + 评测\"三件套。2025 年 7 月 26 日世界人工智能大会期间，上交大发布科学基座大模型 **Innovator**（与**深势科技**、上海算法创新研究院联合研发）及通用科研智能体 **SciMaster**，构建\"搜、读、算、做、写\"全链条能力；2026 年 1 月 29 日，上交大人工智能学院再办\"Agentic Science at Scale\"研讨会，鄂维南院士作主旨报告，同期完成产学研战略签约，并以智能体大赛推动生态共建——赛事吸引 **44 所高校、160 余支队伍**参赛，作品覆盖文献分析、实验设计等环节。\n\nSciMaster 的两个细节对高校信息中心特别有参考价值。一是**思维链可编辑**：研究者可以随时干预智能体的任务执行逻辑，而不是等它跑完再返工；二是上交大**同步建设了智能体评测系统**，把\"科研智能体跑得好不好\"变成可量化、可对比的问题，为规模化部署提供标准化基础设施。效率口径同样来自上观新闻：SciMaster 运行 **6 小时**的成果可比肩资深理论物理学博士 **1—3 个月**的饱和工作量。\n\n### 港科大：AINA 与\"AI for Lab\"，让智能体动手\n\n港科大在 3 月 4 日峰会上披露了正在推进的\"AI for Lab\"计划，开发实验室智能体 **AINA**，方向是主动推理与自动化实验的深度融合。校长叶玉如之外的另一个案例来自郭毅可院士团队：其智能体系统**仅用两天**自动生成了\"活化污泥水处理\"的完整实验室工作流程，包括任务拆解、报告生成、授权批准、自动修改直至最终报告，实现从教授指令到成果产出的全自动运行。这条路线的关键不是模型参数，而是智能体与实验室授权、审批、设备控制这些\"脏活\"接口的打通。\n\n### 国家超算互联网：把智能体做成公共基础设施\n\n**国家超算互联网**给出了第四种路线：不自建单点智能体，而是做生态。2026 年 9 月 15 日算力网发展大会上，曙光智算总裁何牧君披露：平台注册用户超 **170 万**，汇聚超 **350 万 CPU 核心、25 万 GPU 卡**，国产算力占比 **99% 以上**；已建成材料计算、工业仿真等 **6 大智能体矩阵**，覆盖 **170 余个**核心计算场景，累计上线智能体 **400 余个**、知识库 **1000 余个**、MCP（科学计算调用协议）工具 **13000 余个**、技能 **1 万余项**。普通科研人员依托 **1.6 万余个**内容组件与对话式构建工具，无需精通编程即可\"搭积木\"式组建专属科学计算智能体。平台已与**北京大学、东南大学、华大基因**等数十家高校院所及企业合作，典型成果包括国产第一性原理软件 **ABACUS** 与 GPU 加速分子动力学工具 **SPONGE**；配套的伙伴模式提供最高 **50 万元**经费或等额算力、最高 **60%** 算力收益分成，每月举办 20 场以上 Workshop。对高校而言，这是一个可以直接\"接入而不重建\"的公共能力。\n\n### 两个轻量化信号：MatBrain 与书生-S2\n\n**中国科学院深圳先进技术研究院**喻学锋团队 2026 年 9 月 10 日在《自然-机器智能》发布的\"**材智云脑 MatBrain**\"，代表了对\"堆参数\"路线的反向思考：由 **30B** 参数的 Mat-R1（负责\"想\"——材料知识理解、科学推理、结果判断）与 **14B** 参数的 Mat-T1（负责\"做\"——调用材料数据库、结构生成模型与计算软件）组成双模型协作架构。训练侧用了约 **25.2 万条**高质量材料指令数据；工具侧建成 Mat-MCP 平台，把 Materials Project、MatterGen、Pymatgen、CHGNet、VASP 统一封装为可调用工具，并用 **2 万个**复杂材料科研问题做强化学习。结果：材料预测综合准确率较 **GPT-5、DeepSeek-R1** 等大模型提升 **66%**，硬件部署成本降低**超 95%**——智能体得以从大型计算中心走向普通实验室工作站。其电催化剂应用完成了从科学假设、**3 万个**候选结构生成、多阶段计算筛选到实验验证的完整链条，团队还在推进具身智能\"机器人科学家\" Dr. Mind。\n\n模型侧的对应信号是 **上海人工智能实验室** 2026 年 9 月 13 日在浦江创新论坛发布的\"**书生-S2**\"：重点提升长程科研能力与智能体能力，在 Biology-Instructions、Mol-Instructions 等生命科学与材料任务评测上处于开源模型第一梯队。长程任务对持续执行和上下文保持的要求，正是科研智能体区别于聊天助手的地方。\n\n## 三、海外参照：架构怎么设计，可靠性怎么兜底\n\n**Google DeepMind** 的 **AI Co-Scientist**（基于 Gemini 的多智能体科研系统）与**杜克大学**的联合升级版本，是当前\"实验室在环\"最完整的公开样本，论文编号 arXiv 2602.03837。此前版本只做\"计算内假设生成\"；升级后首次以真实实验执行为基础闭环。材料科学部分的验证全部在杜克大学王浩哲课题组完成：针对实验室自建 CVD 系统的几何结构与原料，Co-Scientist 从 **272 个**候选方案中提出以六氯乙烷替代剧毒四氯化钛作为前驱体，经 **25 轮**迭代生长出与 Ti₃C₂Tₓ MXene 晶格特征高度一致的二维层状晶体；在没有任何历史配方参考的情况下，仅凭设备硬件约束生成完整工艺参数，**第一次尝试**即合成出三角形单晶尺寸超 **50 微米**的单层 MoS₂，推广到此前从未合成过的 MoSe₂ 和 WS₂ 同样一次成功，借助 Gemini 3 Deep Think **数分钟内**生成配方并转化为设备控制指令，三种材料首次生长全程约 **一小时**。生物学部分与**哥伦比亚大学**合作，从稀疏成像数据预测工程大肠杆菌群集形态，四项形态指标中三项与未发表的湿实验测量定量吻合。\n\n对高校治理更有参考价值的是其可靠性设计：将幻觉与抄袭惩罚写入优化目标，论文中每一项定量结论与原始实验运行日志逐条比对；一项 **30 位**领域专家、共 **450 次**独立评审的双盲研究证实这些机制显著降低严重幻觉与抄袭发生率；内置安全系统拒绝了 **98.7%** 的有害研究请求。这组做法直接回应了学界对\"AI 科研编造结果\"的两大质疑，也值得写进任何校级科研智能体的验收标准。\n\n文献侧的基础设施则以 **Ai2（艾伦人工智能研究所）与华盛顿大学**的 **OpenScholar** 为代表：基于 **4500 万篇**论文构建检索增强系统，优化后的 **8B 参数**模型在专家对比中，**20 位**专家的 **500 次**实验里有 **72%** 认为 OpenScholar 的输出超过人类专家写的答案——而 GPT-4o 在同类任务中的引用捏造率高达 **78%—90%**。该项目从数据、代码到模型权重全部开源，2026 年 2 月 4 日登上《自然》。对预算有限的高校，OpenScholar 证明\"小模型 + 好语料 + 强检索\"可以支撑起可审计的引用质量。\n\n## 四、主要科研智能体与平台盘点\n\n| 系统/平台 | 开发方 | 架构与分工 | 覆盖环节 | 关键数字 |\n| --- | --- | --- | --- | --- |\n| 大圣（星河启智） | 上智院＋复旦大学 | 多模态科学大模型＋300 余个 Skills＋群体记忆，中心化决策调度多智能体 | 假设—实验—验证—迭代闭环 | RNA 分类准确率 96%；siRNA 成功率提升超 50% |\n| SciMaster / Innovator | 上海交大＋深势科技等 | 科学基座模型＋通用智能体，思维链可编辑，配套评测系统 | 搜、读、算、做、写全链条 | 6 小时约等于博士 1—3 个月工作量；大赛 44 校 160 余队 |\n| AINA / AI for Lab | 香港科技大学 | 主动推理＋实验室自动化融合 | 实验室工作流自动生成与执行 | 活化污泥水处理全流程 2 天自动完成 |\n| 超算互联网智能体生态 | 曙光智算（国家超算互联网） | 对话式构建＋1.6 万余组件＋MCP 工具 13000 余个 | 材料计算、工业仿真等 170 余个场景 | 注册用户 170 万；智能体 400 余个；伙伴最高 50 万元支持 |\n| Science Navigator | 北京科学智能研究院＋深势科技 | 2 亿篇文献＋9000 万学者知识库，多模态检索 | 学术搜索、问答、情报订阅 | 文献超 2 亿篇；实时更新＋订阅推送 |\n| Co-Scientist | Google DeepMind＋杜克大学等 | Gemini 多智能体＋实验室在环，幻觉/抄袭惩罚入目标 | 假设—真实实验—论文 | 一次长出三种单层半导体；拒绝 98.7% 有害请求 |\n| AI Scientist-v2 | Sakana AI | 智能体树搜索，开放式探索 | 选题—实验—论文—评审 | 首篇全 AI 论文通过 ICLR 2025 workshop 评审 |\n| Agent Laboratory | AMD＋约翰斯·霍普金斯大学 | PhD/Postdoc/ML 工程师/Professor 四代理分工 | 文献综述—实验—报告 | 研究成本下降 84% |\n| MatBrain | 中科院深圳先进院 | 30B 推理模型＋14B 执行模型双协作，Mat-MCP 工具平台 | 材料结构生成—筛选—验证 | 准确率较大模型提升 66%；部署成本降超 95% |\n\n## 五、对高校信息中心意味着什么\n\n第一，**编排能力正在从院系自研走向校级服务**。CERNET\"主任谈\"栏目梳理的西安交通大学、南开大学、西安电子科技大学、同济大学四校实践显示，高校智能体建设的共同问题已从\"要不要建\"转向\"广撒网培育生态还是集中力量打造标杆\"；上海交大网络信息中心与华为合作的\"致远一号\"智能体模式（2026 年 4 月研讨会吸引全国 30 多所高校参与，以\"云养虾\"等真实场景做规模化验证）说明，校级智能体平台完全可以同时承载科研、教学与管理场景。政策端，教育部在 2026 年 3 月 31 日国家教育数字化战略行动部署会上明确以\"人工智能+教育\"推动全场景融合——科研智能体是其中最难也最有显示度的部分。\n\n第二，**工具协议是新的\"系统接口\"**。国家超算互联网的 MCP 工具、MatBrain 的 Mat-MCP 平台、Co-Scientist 的设备指令转换，本质上都在做同一件事：把数据库、计算软件、实验设备封装成智能体可调用的标准工具。高校信息中心手里握着校级 HPC 集群、正版软件、仪器预约系统——这些正是科研智能体最缺的\"手和脚\"。谁先把校内科研工具 MCP 化，谁的智能体生态就有先发的供给优势。\n\n第三，**成本结构决定了轻量化路线的可行性**。MatBrain 用 30B+14B 的组合把部署成本压低 95%，意味着院级工作站也能跑科研智能体；而\"大圣\"、Co-Scientist 这类全流程系统仍依赖大规模算力与实验室改造。高校不必二选一：文献问答与综述类场景用轻量模型加检索即可（OpenScholar 路线），湿实验闭环再接入校级平台。\n\n## 给高校的可操作清单\n\n1. 盘点校内可被智能体调用的科研工具（计算软件、数据库、仪器预约、高性能集群接口），制定 MCP 化封装的优先级清单，先从调用量最大的十件工具做起。\n2. 在校级 AI 平台上开出一个\"科研智能体工作区\"，支持课题组用对话式工具搭建专属智能体，并接入统一的模型网关与 Token 计量，避免各院系重复采购。\n3. 参照上海交大 SciMaster 的做法，同步建设智能体评测基准：至少覆盖引用准确率、工具调用成功率、任务完成率三个指标，将其纳入采购与验收标准。\n4. 把\"结论与实验日志逐条比对\"写入科研智能体的可信要求，参考 Co-Scientist 的双盲评审机制，对涉及发表的智能体产出建立留痕审计。\n5. 与国家超算互联网等公共平台建立合作而非竞争关系：校级平台负责身份、计费与工具封装，公共平台提供弹性算力与成熟智能体市场，善用其最高 50 万元经费或等额算力的伙伴激励。\n6. 在图书馆或学科服务中心部署文献检索增强型智能体（OpenScholar 一类的开源路线），优先解决综述与情报订阅的引用幻觉问题，这是投入产出比最高的第一步。\n7. 为科研智能体制定分级授权：纯文献任务开放给全体师生，涉及真实实验设备与危险试剂的任务保留人工审批环节，参照\"活化污泥工作流\"中\"授权批准\"环节的人工卡点设计。\n8. 用真实场景赛事拉动生态：借鉴上交大智能体大赛（44 校 160 余队）的模式，把校内分散的课题组需求转化为可复用的技能包与智能体模板。\n\n## 还没解决的问题\n\n1. **实验反馈周期与智能体节奏不匹配。**伦敦大学学院汪军教授在港科大峰会上指出，机械臂损坏、设备故障会中断实验，化学与材料实验的反馈周期以天计，与 AI 的快速推理形成结构性矛盾；缺乏对应的理论与方法支撑。\n2. **纯数据驱动难以捕捉物理规律。**港科大陆萌茜团队的经验显示，超 15 天的气象预报稳定性较差，AI 与物理模型的深度融合仍是未完成课题；材料、气候等复杂系统尤其明显。\n3. **评测标准远未收敛。**各家平台的\"效率提升\"口径互不可比——\"6 小时等于博士 1—3 个月\"与\"成本下降 84%\"来自不同任务、不同基线，高校目前没有跨平台可比的第三方评测。\n4. **跨学科复合型人才缺口。**既懂领域科学又掌握智能体工程的人，正是建设与运营这类平台的主力，而这恰是高校信息中心当前最难招聘的岗位类型。\n5. **知识产权与学术伦理规则滞后。**AI 主导完成的实验与论文在署名、专利归属、责任认定上尚无公认框架，Co-Scientist 拒绝 98.7% 有害请求的安全机制也提示：恶意或高危研究请求的治理，需要在校级层面提前设防。\n"},"report-tech-frontier":{"id":6,"slug":"report-tech-frontier","title":"技术侧写：科学大模型的代表成果，与影响选型的三个新变量","kind":"report","dek":"气象三条路线（伏羲的端到端、风乌的多模态、NowcastNet 的神经演变算子），机器化学家与 E2GNN 的可解释路径，Evo 与女娲的领域基础模型——以及 Terminal-Bench-Science 从 20% 跳到 65% 之后，高校该怎么重新算选型这笔账。","tags":["伏羲","风乌 GHR","NowcastNet","机器化学家","E2GNN","Evo 基因组模型","Terminal-Bench-Science"],"sources":[{"url":"https://lygw.ai/blog/20250904-ai4s/","date":"2025-09-04","site":"lygw.ai","title":"国内高校 AI4S 实践凝练与洞察：从“范式革命”到“务实深耕”"},{"url":"https://www.thepaper.cn/newsDetail_forward_29355037","date":"2026-08-29","site":"澎湃新闻 · 学术头条","title":"Science 最新封面：AI 大模型跨越物种边界、解码生命“密码全书”"},{"url":"https://segmentfault.com/a/1190000048257000","date":"2026-09-02","site":"SegmentFault 思否","title":"最强模型 Claude Fable 5.1 发布：科研跑分翻倍，缓存成本骤降 75%"},{"url":"https://finance.sina.com.cn/tech/roll/2026-09-04/doc-iniqrpqy0847298.shtml","date":"2026-09-04","site":"新浪科技","title":"OpenAI 最强模型 GPT-6 Astra 发布"},{"url":"https://cloud.tencent.com/developer/news/4558971","date":"2026-09-04","site":"腾讯云开发者社区","title":"AI 大模型：OpenAI GPT 6 Astra 发布，推理跑分接近饱和"},{"url":"http://finance.eastmoney.com/a/202308192818121790.html","date":"2026-09-01","site":"东方财富网","title":"深势科技完成新一轮融资，将 AI for Science 引入大模型时代"},{"url":"https://cn.chinadaily.com.cn/a/202501/09/WS678473baa310b59111dad6f7.html","date":"2025-01-09","site":"中国日报网","title":"科学大模型：“上线”之路还有多远"},{"url":"https://finance.eastmoney.com/a/202411123237446794.html","date":"2026-08-30","site":"东方财富网","title":"上海首发四款垂直大模型，聚焦 AI 与基础科学研究的融合发展"},{"url":"https://local.cctv.com/2025-04-30/ARTIh8e9J1YO2eEvWIUMX4Kb250430.shtml","date":"2025-04-30","site":"央视网","title":"复旦漆远：共建科学智能开放生态"}],"region":"国内外","layers":["tools","data"],"issue_no":null,"pinned":false,"word_count":5668,"published_at":"2026-09-05T15:24:59.459+00:00","body_md":"## 一、为什么需要一份\"技术侧写\"\n\n平台与建制决定 AI4S 能不能跑起来，模型与算法决定跑到什么水平。这份侧写不追求覆盖全部成果，只挑三类信息：**代表性模型的技术路线**（可复用）、**公开评测结果**（可比较）、以及**通用大模型在科学基准上的最新变化**（影响高校选型）。\n\n## 二、气象：三条技术路线的分野\n\n气象是 AI4S 最早跑出颠覆性成果的领域。传统数值天气预报（NWP）计算成本高昂且提升缓慢，AI 大模型改变了这个局面。国内三支代表性队伍走出了三条不同路线。\n\n### 复旦\"伏羲\"：端到端优化\n\n目标非常明确——直接挑战并超越全球标杆、欧洲中期天气预报中心（ECMWF）的高分辨率预报（HRES）。按 ECMWF 实时评测，\"伏羲\"已成为综合预报精度最高的模型之一。\n\n核心创新是**端到端架构**：不只是预报模型，而是集成资料同化与预报的完整系统，能直接对预报结果做端到端优化，避免传统方法中同化与预报环节割裂导致的误差累积。模型结构采用基于 U-Net 与 Transformer 的 **U-Transformer** 架构，并通过**级联（Cascade）方式**整合多个模型分别优化不同预报时段，提升整体预报时长与精度。\n\n工程与业务侧的公开记录：参与中国气象局示范计划时，16 项指标中 12 项单项指标、3 项综合指标长期位居榜首；团队不仅用开源数据训练，还把预测数据与气象大数据开源；实现四季节预报，关键指标有效时长显著提升；获国际基础科学大会 2025 年度科学前沿奖。协作模式是典型的\"高校 + 研究院 + 国家机构\"：复旦大学（AI3 研究院、大气与海洋科学系）、上智院、中国气象局。\n\n### \"风乌\"：多模态多任务\n\n由上海人工智能实验室联合中国科学技术大学、上海交通大学、南京信息工程大学、中科院大气物理研究所及上海中心气象台共同发布，主攻高分辨率与长时效。最新版本 **风乌 GHR** 把有效预报时间提升至 11.25 天、预报分辨率提升至 10 公里级别，在 80% 的评估指标上超越 DeepMind 的 GraphCast。\n\n技术路线核心是**多模态多任务深度学习**：把气温、风速、气压等不同大气变量视为独立\"模态\"，采用多模态 Transformer 架构处理，以更深入地挖掘变量间的复杂关联。组织形式是\"新型研发机构牵头、多方参与\"。\n\n### 清华 NowcastNet：物理规律嵌入神经网络\n\n与前两者关注中长期预报不同，NowcastNet 专注短时强降水、冰雹等极端天气的**临近预报（0—6 小时）**，成果发表于《Nature》。\n\n最大亮点是**数据驱动与物理驱动的深度融合**。传统 AI 气象模型常被诟病为缺乏物理可解释性的\"黑箱\"，该团队创建了模拟降水物理过程中尺度运动的**\"神经演变算子\"（Neural Evolution Operator）**，无缝嵌入深度学习网络——相当于给模型注入物理学知识，使其既能从数据学模式，又遵循大气运动基本规律，在预测小概率极端事件时更可靠。合作方是国家气象中心、国家气象信息中心等业务单位。\n\n**可复用结论**：架构创新（U-Transformer + 级联）、多模态融合（把物理量当模态）、物理知识嵌入（神经算子）是三条可组合的路线。对高校而言，第三条路线门槛最高但科学价值最大，也最能回应\"不可解释\"的质疑。\n\n## 三、材料与化学：机器化学家与高效势函数\n\n### 中科大\"机器化学家\"：软硬件一体的自主实验平台\n\n目标是打造能模拟甚至替代人类科学家做化学实验的智能平台，实现从文献理解、假设提出到实验执行、结果分析的全流程自动化。平台不是单一软件，而是**软硬件深度融合的系统**：硬件集成高精度机械臂、视觉系统与各类自动化实验模块；软件核心是能自主学习决策的 AI 大脑。\n\n量化能力：可在两周内学习 5 万篇学术论文，六周内验证超过 376 万种实验配方；平台能在一两周内完成人类科学家可能需要一生才能完成的筛选工作。\n\n标志性成果是破解了困扰多相催化领域近 50 年的**\"金属-载体相互作用\"（MSI）**难题：先汇总大量文献实验数据，再用可解释 AI 算法（结合压缩感知与领域知识）从高达 300 亿个数学表达式中筛选出能准确描述该作用的物理控制方程；过程中\"复原\"了缺失的实验数据，并发现\"金属-金属相互作用\"这一全新关键变量，提出具有普适性的\"强金属-金属作用原理性判据\"，成果发表于《Science》。\n\n**方法论价值**：可解释 AI + 压缩感知 + 领域知识，是从\"黑箱预测\"走向\"发现物理规律\"的一条已验证路径。\n\n### 北大 E2GNN：又快又准的原子间势\n\n分子动力学模拟的核心环节是精准高效地预测原子间相互作用势能。传统方法要么精度高但慢（第一性原理计算），要么快但精度不足。北大团队的**等变图神经网络 E2GNN** 在多个基准上超越现有代表性模型，成果发表于《npj Computational Materials》。\n\n技术关键是**对物理对称性（等变性）的巧妙处理**：能量预测必须对体系旋转平移保持不变，力的预测则需随之等变；传统模型为实现这点常依赖复杂的高阶张量运算，开销巨大。E2GNN 采用简洁的**\"标量-向量\"混合表示**编码等变特征，并引入**全局消息传递机制**精确捕捉长程原子相互作用，在满足物理约束的同时极大提升效率。\n\n效果：基于 E2GNN 力场对固态（LiPS）、液态（H₂O）、气态（CH₄）体系的模拟，预测精度可达昂贵的第一性原理计算级别，速度快了几个数量级。\n\n### 深势科技的预训练模型体系\n\n深势科技把 AI4S 带入\"预训练模型时代\"，三条主线值得追踪：**Uni-Mol** 分子表征大模型（在 OGB-LSC 量子化学性质预测任务上夺冠，服务制药、催化、OLED 等场景）、**Uni-RNA**（提升 mRNA 疫苗设计、RNA 结构预测、ASO 开发、siRNA 疗法、靶向 RNA 小分子、Aptamer 研发等几乎所有 RNA 相关场景的模型能力）、**DPA 预训练模型**（提升深度势能模型的场景迁移与泛化能力，已在高性能合金、半导体及电池材料设计中验证领先性）。这些模型通过玻尔（Bohr）平台向高校供给，武汉大学数智教育实践创新平台的算力即由该平台支持。\n\n## 四、生命科学与医药\n\n### 复旦 CRAFTS：给冷冻电镜装\"导航\"\n\nRNA 的复杂三维结构决定生物学功能，冷冻电镜是解析关键技术，但海量 RNA 序列中只有极少数能形成稳定结构，实验筛选成本极高。复旦孙思琦团队的 **CRAFTS** 通过**对比学习**先在庞大的 Rfam 数据库上学会区分哪些序列对属于同一 RNA 家族（领悟决定结构共性的深层特征），再在已知有结构/无结构的 RNA 序列上微调，从而判断任意新序列形成稳定结构的可能性，成果发表于《Science》。这相当于给高成本实验装了低成本导航。\n\n### 上智院的领域大模型群\n\n复旦大学与上智院共同研发的**\"女娲\"系列生命科学大模型**构建了全球首个百亿级参数 RNA 基础模型，其中生物结构大模型支持蛋白质与抗体药物开发；**基因导航大模型**结合图神经网络与调控关系知识图谱提升基因调控预测精度；**生命流体大模型**以全球最大器官流体力学数据库为基础，大幅提升流体模拟效率，用于脑动脉血流等疾病机制研究；**\"观心\"**是全国首个 AI 心脏大模型。2024 年 11 月的科学智能创新论坛还发布了中国首个自主研发的气候科学大语言模型 **Planet Intelligence @ Climate**。\n\n### 清华成像与智能技术实验室：破解医疗 AI 落地三难\n\n医疗 AI 面临三个结构性障碍，清华给出的解法值得信息中心参考：\n\n1. **数据孤岛**（隐私导致难共享）→ 发展**联邦学习**等隐私计算技术，实现多中心联合训练而不共享原始数据，代表性成果发表于《The Lancet Digital Health》；\n2. **标注成本高**（需大量专业医生）→ 开发**弱监督学习**算法，例如让 AI 直接从医生书写的自由文本诊断报告中学习、自动检测 CT 颅内异常，避免像素级精细标注，成果发表于《Cell Reports Medicine》；\n3. **重复开发**（每种疾病/模态都要专用系统）→ 构建**单模态多任务基础模型**，\"一个模型通解多种问题\"，成果见于《Nature Medicine》《Patterns》等。\n\n### 地球科学与数学\n\n- **元古大模型**（中国地质大学（武汉），2024 年 12 月 7 日发布）：地球科学领域垂直大模型，可对古生物化石进行复原；\n- **\"坤元\"**：全球首个多模态地理科学大模型，被称为\"智能地理学家\"；\n- **亲吻数问题**：2026 年上智院联合北京大学、复旦大学团队，用 AI 在这一经典数学难题上取得系统性突破——数学长期被视为 AI 最难介入的领域之一，这一结果具有指标意义。\n- 智源研究院的生物计算大模型搭建了**全球首个数字孪生心脏电功能超实时仿真系统**，包含 19 种细胞生理状态变量和 70 多个公式。\n\n### 基因组基础模型 Evo（海外对照）\n\n斯坦福大学 Brian L. Hie 团队以封面文章形式在《Science》发表 **Evo**：基于 **3000 亿 DNA token** 训练的大规模基因组基础模型，能在长序列的单碱基分辨率下预测与生成 DNA、RNA 和蛋白质序列，跨物种基因预测超越特定模型。模型专为捕捉生物学两个核心方面设计——中心法则的多模态性与进化的多尺度特性。Evo 生成的多基因系统成功率接近 50%，生成的 CRISPR-Cas9 蛋白经实验验证具有功能活性，全基因组生成结果在基因组组织、编码密度上与天然基因组高度相似。评论者的评价是：\"首次从进化多样性中提取出 DNA 的'语法规则'。\"\n\n**对高校的提示**：Evo 的训练规模意味着这类\"生命基础模型\"只能由具备大规模算力与数据的机构产出，多数高校的合理策略是**接入 + 微调 + 领域适配**，而不是自研底座。\n\n## 五、通用大模型的科学能力：正在剧烈变化的一格\n\n高校选型的另一条线是通用大模型在\"自主科学研究\"基准上的跃升。2026 年 9 月的两次发布值得记录。\n\n**Anthropic Claude Fable 5.1 / Mythos 5.1**（2026 年 9 月 2 日）：在衡量自主科研能力的 Terminal-Bench-Science 0.1 上得 52.6%，而上代 Fable 5 为 24.7%、GPT-5.6 Sol 为 22.4%——**一个数量级的跳变**；Terminal-Bench 4.0 代码工程能力从 42.0% 升至 55.8%（Mythos 版 60.9%）；缓存读取价格同步骤降 75%，高强度 Agent 任务总成本最高可省 45%。Mythos 5.1 与 Fable 共用权重，但开放更高风险能力上限，仅向通过 Cyber Verification Program（CVP）与 Life Sciences Verification Program（LSVP）审核的美国机构开放。**生命科学方向设专门审核通道**，说明高风险科研能力已经开始分级供给。\n\n**OpenAI GPT-6 Astra**（2026 年 9 月 4 日）：Terminal-Bench-Science 0.1 得 64.6%，高于两天前的 Fable 5.1，且完成同等任务的估计 API 成本低约 31%（更低成本设置下仍得 61.1%）；Terminal-Bench 4.0 得 57.9%；FrontierMath Tier4 得 97.6%；ARC-AGI-3 得 99.9%（GPT-5.6 Sol 为 7.8%，人类水平约 48%）；OSWorld 2.0 得 72.6%，单项任务平均耗时从约 75 分钟缩短到 40 分钟。OpenAI 称 Astra 已帮助解决数学领域长期存在的开放性问题，包括在素数间隔研究中取得两个新的理论结果。定价为每百万输入 token 10 美元、输出 50 美元（为前代 2.5 倍），提供速度提升 2.5 倍的快速模式。\n\n**这对高校意味着什么**：\n1. **科研 Agent 的可用性阈值被跨越**。Terminal-Bench-Science 从 20% 量级跳到 50%—65%，意味着\"让模型自己跑一段科研流程\"从演示变成可评估选项。\n2. **成本结构在重构**。缓存读取降价 75%、Prompt 缓存减免输入 Token 计费，直接改善高校\"统一兜底 Token 成本\"模式的可持续性。\n3. **合规与分级供给成为新变量**。生命科学高风险能力需要机构审核（LSVP），国内高校在采购海外模型用于生物、化学等敏感方向时会遇到额外门槛，反过来会加强本地化部署与国产模型适配的动力。\n4. **选型要看\"单任务成本\"而不是单价**。GPT-6 Astra 单价是前代 2.5 倍，但因输出 token 减少、执行时间缩短、重试次数降低，多项基准估算的单任务成本反而下降。校级平台计费策略应据此从\"按 Token 定额\"转向\"按任务预算\"。\n\n## 六、还没解决的技术瓶颈\n\n- **AI 幻觉与可解释性**：大模型可能生成看似合理但完全错误的结论；即使是表现惊艳的模型，其背后原理也难以说清。在要求严谨、可复现的科学研究中，不可解释的\"黑箱\"是重大隐患。NowcastNet 的神经算子与中科大的可解释 AI 是两条有效路径，但都还属个案。\n- **物理知识与数据驱动的耦合**：把数百年积累的物理、化学、生物知识有效融入数据驱动模型，是提升可靠性与泛化能力的关键，简单拼接或完全抛弃物理规律都不是最优解。\n- **通用性与开发成本的矛盾**：AlphaFold 一类的成功多是针对特定科学问题的专用模型，通用 AI 科研工具仍然稀缺、开发成本高昂，难以像 Python 那样成为普惠的科研基础设施。北大林周辰教授的这一判断，解释了为什么\"星河启智\"要把 400 余个模型与工具、Intern-Discovery 要把 200 余个智能体集中开放——**用平台规模对冲单点工具的通用性不足。**\n- **模型评测体系仍在早期**：上智院把\"科学大模型评测体系\"列为四大重点布局之一，说明连头部机构也认同学界缺乏公认的科学模型评测标准。高校在选型时应自建小规模领域基准，而不是直接采信厂商跑分。\n"}});
window.__AI4S_API__.articleDetails=Object.assign(window.__AI4S_API__.articleDetails||{},{"report-token-service":{"id":2,"slug":"report-token-service","title":"Token 即基础设施：高校信息中心的大模型统一服务实践","kind":"report","dek":"清华 easycompute 的券化算力与免申请自动续期、“清小答”由学校兜底 Token 成本、农大本地化部署 4 小时 5700 万 Token、武大 40 门课的 AI 实训基地；再加上网关、四角色对账与 Token 成本失控的治理清单。","tags":["Token 服务平台","MaaS","算力券","大模型 API 网关","配额与全成本核算","知识库众包运营"],"sources":[{"url":"https://m.sohu.com/a/1049819293_121124031/","date":"2026-07-13","site":"搜狐网","title":"@全体 THUer 续上了！清华专属免费算力持续可用"},{"url":"https://www.toutiao.com/w/1870693389993028/","date":"2026-07-15","site":"今日头条","title":"清华大学为全校学生配备 AI 学伴“清小答”"},{"url":"https://news.cau.edu.cn/zhxwnew/f007b38d5f7b4b35a0e1a536088e1665.htm","date":"2025-02-21","site":"中国农业大学新闻网","title":"中国农业大学 AI 大模型平台正式上线"},{"url":"https://uc.whu.edu.cn/info/1646/118851.htm","date":"2025-03-04","site":"武汉大学本科生院","title":"携手 DeepSeek，数智武大：数智教育实践创新平台重磅升级"},{"url":"https://lib.sustech.edu.cn/2026/0904/c1405a8371/page.htm","date":"2026-09-04","site":"南方科技大学知识苑","title":"Trial on the LeapSpace AI Platform"},{"url":"https://juejin.cn/post/7666019880677523465","date":"2026-07-27","site":"掘金","title":"MAI Gateway｜AI 网关如何解决高校课题组和实验室共享模型的账目问题"},{"url":"https://www.geekpark.net/news/363815","date":"2026-05-08","site":"极客公园 / IDC","title":"2025 大模型公有云服务：中国企业级 MaaS 市场 Token 调用量"},{"url":"https://blog.csdn.net/weixin_33212799/article/details/164279548","date":"2026-09-01","site":"CSDN","title":"大模型 Token 成本失控：预算配额、用量监控与告警体系建设指南"},{"url":"https://blog.csdn.net/weixin_44661794/article/details/162974878","date":"2026-08-24","site":"CSDN","title":"大模型 API 网关统一管控架构实战：多模型接入、计费统计"},{"url":"https://blog.csdn.net/gitblog_01164/article/details/163499879","date":"2026-08-05","site":"CSDN","title":"new-api：新一代 AI 模型网关与资产管理平台"}],"region":"国内为主","layers":["model","compute"],"issue_no":null,"pinned":true,"word_count":3990,"published_at":"2026-09-05T15:24:58.626+00:00","body_md":"## 一、为什么是 Token：从\"买卡\"到\"发额度\"\n\n国家数据局把 Token（词元）称为\"智能时代的价值锚点\"，是连接技术供给与商业需求的**结算单位**。这个定义放到高校场景里非常贴切：对师生来说，AI 能力的最小可分配单位不是 GPU 卡时，而是一次调用消耗的 Token。\n\nIDC 披露的数据可以说明量级变化：2024 年中国企业级 MaaS 市场按调用量统计为 114 万亿 Tokens，2025 年跃升至 1944 万亿 Tokens，同比增长约 16 倍；IDC 预计 2026 年还会同比增长约 20 倍到 40000 万亿 Tokens。驱动力是多模态成熟与 Agent 类应用规模化落地——每一次交互消耗的 Token 量级都在抬升。\n\n对高校信息中心来说，这意味着一件事：**大模型不再是\"上个聊天机器人\"的项目，而是要当成水电网一样的校内公共服务来发额度、做计量、控成本。** 一个直观的数字来自中国农业大学：其 AI 大模型平台上线 4 小时，2400 位师生体验、提问 7200 次、消耗 Token 5700 万。按这个速率外推，全校师生常态使用后的 Token 消耗是必须提前规划的预算项。\n\n## 二、四种在校内落地的服务形态\n\n### 形态一：统一身份 + 算力券 + MaaS（清华大学 easycompute）\n\n清华的做法把\"发额度\"工程化了。师生登录后通过统一身份认证进入 easycompute 平台，点击\"登录领券/使用\"即自动发放 1000 元算力券，可在\"我的优惠券\"中查看使用；无需填表申请、无需重新申领、无需导师审批，系统统一自动更新有效期。2026 年暑期该券在首轮延期基础上再次续期至 8 月 31 日，账户内未用完的余额与权益完整保留，配套的智能编码福利同步续期（套餐有效期 3 个月）。\n\n平台侧持续开放 4090、5090 等全系主流 GPU 算力，内置一站式大模型 MaaS 服务，支持海量 Token 高效调用，适配大模型微调、长文本推理、智能体交互等高频场景；主流 AI 框架、开发环境与常用数据集提前预装、开箱即用。使用规则也写得很清楚：算力券仅限本人用于校内课程学习、学术科研、科创实践等非营利用途，禁止转借、倒卖与违规占用。\n\n这套设计的可复用点是三条：**券化额度**（预算可视、可延期、可结转）、**统一身份直通**（零申请门槛）、**环境预装**（把\"搭环境\"这一最大隐性成本前置消化）。\n\n### 形态二：学校统一承担 Token 成本（清华\"清小答\"）\n\n同样是清华，面向学生的\"清小答\"走的是另一条路：2024 年 8 月 14 日新生开学第一天上线，基于大模型智能体技术，覆盖选课指导、生活问题、科研答疑、数据分析、PPT 制作等从入学到毕业的全周期场景，**由学校统一承担 Token 成本，学生免费无限使用**。\n\n这是\"普惠型\"与\"配额型\"的分野：面向全体学生的通用助手由学校兜底、不限额；面向科研的重负载训练与推理则发券、按额度管理。两者并行，而不是二选一。\n\n### 形态三：本地化部署的校级大模型平台（中国农业大学）\n\n中国农业大学 AI 大模型平台于 2025 年 2 月 21 日在 PC 端与移动端同步上线，依托学校智算平台算力资源**本地化部署**，支持 DeepSeek-R1、Qwen2.5、Qwen2-VL、Conan-embedding-v1、CosyVoice-300M-SFT、SenseVoiceSmall、Flux.1-dev 等主流模型，覆盖对话、多模态问答、语音合成与识别、文生图。入口做了三路打通：独立网址 ai.cau.edu.cn、学校综合服务平台\"推荐服务—AI大模型\"、移动端企业号。\n\n在此基础上，信息化团队同步开发了\"小鹉哥\"智能体，用于助教、助学、助研、助管。值得关注的是知识库的运营机制：校内知识库尚不完备时，师生可在网上办事大厅的\"981 AI大模型知识库征集\"提交问题与权威答案，由网络技术中心审核后入库。**把知识库建设做成众包 + 审核的常态化流程**，比一次性建库更可持续。\n\n### 形态四：面向教学的 AI 实践平台（武汉大学 × 深势科技）\n\n武汉大学数智教育实践创新平台由深势科技定制，2024 年 9 月上线，落实\"五位一体\"\"四真计算\"\"三教融合\"的数智教育理念；2025 年 2 月重磅升级，正式接入 DeepSeek 系列大模型。平台已有超过 40 门课程上线、累计发布 AI Note 超过 2000 篇、服务师生超过 4000 人，定位为全学科 AI 教学实训基地，并由深势科技玻尔（Bohr）平台提供算力支持。\n\n两个具体做法有借鉴意义：**AI Note**（交互式学习环境，模型生成可视化代码示例，学生走\"理论→实践→反馈\"闭环，例如在可视化界面观察不同优化器对收敛速度的影响）；**AI 助教\"珞珞\"**（动态构建学生学习画像，结合课程内容提供个性化问答，引导\"问题发现—自主探究—认知重构\"的思维训练，并能按学习轨迹推荐补充资料）。师生可在同一平台完成图文教学、代码实训、科研竞赛与科研计算，实现学练一体、研学一体。\n\n此外，图书馆系统也在补位：南方科技大学图书馆于 2026 年 9 月开通 Elsevier LeapSpace 科研级 AI 工作空间试用（9 月 7 日至 10 月 6 日，首次使用需在校内 IP 范围注册），平台汇聚 2000 万余篇全文同行评议文章与图书、超过 1000 家内容伙伴、1 亿余条 Scopus 学术记录，覆盖 7000 多家出版商与 330 个学科，且每个 AI 回答都附带引用与原文链接以便溯源。**采购带引用的科研 AI 空间，是图书馆参与 AI4S 基础设施的低成本入口。**\n\n## 三、Token 服务的治理层：网关、配额与账单\n\n一旦多院系、多课题组接入，平台就会遇到与企业 AI 中台完全相同的问题：接口地址零散、业务代码硬编码模型地址与密钥、Token 消耗统计分散在各处、对内成本核算与对外账单对账困难、异常高频调用挤占算力、Prompt 模板散落与敏感内容直接入模。\n\n行业实践给出的答案是**统一大模型 API 网关**：所有 LLM、Embedding、重排、图像生成接口统一收口，实现路由、鉴权、计费、限流、内容安全审核、Prompt 模板托管一体化管控。开源侧的 new-api / One API 一类项目支持把多家上游转换成 OpenAI 兼容或 Anthropic 兼容格式，配内部充值、配额分配、按请求与按用量计费、缓存命中统计等能力。商业侧的 MaaS 网关则强调统一 OpenAI 格式接口、仅改 `model` 字段即可切换模型、全局 Prompt 缓存带来的输入 Token 计费减免（实测综合成本最高可降 60%—70%）、以及可视化调用监控（调用次数、Token 消耗、首包时延、成功率、异常报错）。\n\n高校场景还有一个企业没有的难点：**一笔模型费用里有四个角色**。学生可能是付款人（先垫付再找导师报销），导师是经费负责人，真正承担费用的是某个纵向/横向项目或校内基金，而实际调用可能来自共享服务器上的批处理脚本。到学期末，付款人、使用人、经费项目、研究任务对不上，账自然难算。常见的错误做法是把一把 Key 放进服务器、代码和课题组群里共用。\n\n大型仪器共享平台早就解决过类似问题：导师建立课题组，学生以个人身份加入，使用记录落到具体成员，费用按项目归集。模型 API 更该被当成\"共享仪器\"而不是\"办公软件\"来管理——**项目—成员—令牌—配额—调用记录五元组对齐**，才能同时满足科研便利与财务合规。需要明确说明边界：网关可以生成用量明细、解释钱怎么花出去了，但不能把供应商账单变成合规票据，也不能替财务判断某笔个人订阅是否属于可报销范围。\n\n## 四、成本失控的真实形态与检查清单\n\nToken 成本失控通常不是在选型那一刻决定的，而是在调用量上来之后悄悄发生的。计量口径要先分清楚：中文一个汉字通常对应 1—2 个 Token，英文一个单词可能被拆成一个或几个 Token，代码里的空格、缩进、符号都可能独立成 Token，所以同一段提示词在不同模型间实际消耗并不同——估算不能只看字符数，要看模型返回的 `usage` 字段与服务商计费口径。单次请求成本 = 输入 Token × 输入单价 + 输出 Token × 输出单价，而 Agent 场景会把历史对话、工具返回结果反复塞进上下文，形成乘数效应。\n\n给高校信息中心的落地清单：\n\n1. **分层发额度**：面向全体师生的通用助手由学校兜底不限额（普惠）；面向科研的重负载走算力券/Token 配额（可计量、可延期、可结转）。\n2. **统一入口**：一个 OpenAI 兼容网关，纳管多家模型与本地部署模型；切换模型只改 `model` 字段。\n3. **令牌到人、账到项目**：个人身份认证领券，Key 不共享；调用记录关联项目编号，供财务对账。\n4. **配额 + 超额双策略**：预设配额按测算申请经费并定期充值，同时与服务商约定超额使用，避免高峰期服务中断（上海科技大学实践）。\n5. **缓存优先**：系统提示词与固定 Schema 做全局 Prompt 缓存，长上下文场景做 KV 缓存分片优化。\n6. **监控与告警**：把调用次数、Token 消耗、首包时延、成功率、异常报错做成可视化看板，设预算阈值告警。\n7. **知识库众包**：像农大那样把知识补全做成常态化的征集—审核—入库流程，答案质量决定服务口碑。\n8. **合规前置**：网关层做输入内容审核与敏感拦截，涉密与隐私数据不进公共模型，必要时走本地化部署。\n\n## 五、观察与判断\n\nToken 服务平台正在成为高校信息中心的\"新基建标配\"，但真正拉开差距的不是接了多少模型，而是三件事：**额度发放是否零门槛、调用记录是否能对到项目、知识库是否有常态化运营机制**。前者决定使用率，中者决定可持续性，后者决定服务质量。\n\n下一阶段的变量在成本侧：随着 Agent 类应用把单次交互的 Token 量级抬升一个数量级，\"学校统一兜底\"的模式会越来越贵。可以预期的演进是按人群与任务分级定价、把缓存命中率纳入平台 KPI、以及把校内推理负载逐步迁移到本地部署与国产算力上。\n"},"weekly-2026-08-31":{"id":7,"slug":"weekly-2026-08-31","title":"周度综述（建库首期）：高校把平台服务化，海外把基建国家化，模型层科学基准跳一个量级","kind":"weekly","dek":"上海大学公开 AI 智慧平台的建设逻辑，南科大图书馆引入带引用的科研 AI 工作空间，江苏揭牌全国首个省级 AI4S 公共算力中心；NSF 启动州与区域 AI 基础设施中心计划；Terminal-Bench-Science 从 20% 量级跳到 50%—65%。","tags":["上海大学","南方科技大学","江苏 AI4S 算力中心","NSF Hub 计划","Fable 5.1","GPT-6 Astra"],"sources":[{"url":"https://cernet.edu.cn/info/focus/rd_xin_wen/202608/t20260820_2766409.shtml","date":"2026-08-20","site":"中国教育和科研计算机网 CERNET","title":"上海大学：怎样建好、用好 AI 智慧平台"},{"url":"https://lib.sustech.edu.cn/2026/0904/c1405a8371/page.htm","date":"2026-09-04","site":"南方科技大学知识苑","title":"Trial on the LeapSpace AI Platform"},{"url":"https://www.sohu.com/a/1069781691_121901402","date":"2026-08-31","site":"搜狐网","title":"AI4S 赋能科研创新：江苏打造全国首个省级公共算力中心"},{"url":"https://www.idcpc.cn/post/2016.html","date":"2026-09-01","site":"IDCPC","title":"中国移动-浙江大学启真算力中心"},{"url":"https://finance.eastmoney.com/a/202506233438033561.html","date":"2026-08-30","site":"东方财富 / 上观新闻","title":"定义 AI4S 的未来标准 上海交通大学发布超级科研平台"},{"url":"http://smse.whut.edu.cn/xydt/202608/t20260814_1413959.shtml","date":"2026-08-14","site":"武汉理工大学材料科学与工程学院","title":"腾讯云来院开展 AI for Science 合作交流"},{"url":"https://www.toutiao.com/w/7670852130735686444/","date":"2026-08-06","site":"今日头条","title":"华南农业大学与联想合作搭建 AI 算力平台"},{"url":"https://stem.zjnu.edu.cn/2026/0815/c9134a580020/page.htm","date":"2026-08-14","site":"浙江师范大学","title":"美国 NSF 和区域 AI 基础设施中心将推动全国范围内人工智能科学研究发展"},{"url":"https://carcc.org/2026-08-27/all-things-ai-september-2026/","date":"2026-08-27","site":"CaRCC","title":"All Things AI – September 2026"},{"url":"https://arxiv.org/abs/2608.26519","date":"2026-08-27","site":"arXiv","title":"Report of the 2026 Workshop on Next-Generation Ecosystems for Scientific Computing"},{"url":"https://www.stdaily.com/web/English/2026-08/25/content_568917.html","date":"2026-08-25","site":"Science and Technology Daily","title":"AI for Science Shifts from Efficiency Boost to Systemic Reform of Research"},{"url":"https://segmentfault.com/a/1190000048257000","date":"2026-09-02","site":"SegmentFault 思否","title":"最强模型 Claude Fable 5.1 发布：科研跑分翻倍，缓存成本骤降 75%"},{"url":"https://finance.sina.com.cn/tech/roll/2026-09-04/doc-iniqrpqy0847298.shtml","date":"2026-09-04","site":"新浪科技","title":"OpenAI 最强模型 GPT-6 Astra 发布"}],"region":"国内外","layers":["compute","model","region"],"issue_no":null,"pinned":false,"word_count":4231,"published_at":"2026-09-05T01:00:00+00:00","body_md":"> 本期为观测台首期简报，覆盖近期可核对的公开动态。自下一期起，每天 09:00（Asia/Shanghai）自动抓取最近一日新进展。\n\n## 一句话概览\n\n国内高校的动作集中在**\"平台服务化\"**：上海大学把超算底座包装成面向全校的一站式 AI 智慧平台，南方科技大学图书馆引入带引用的科研 AI 工作空间，江苏揭牌全国首个省级 AI4S 公共算力中心。海外则是**\"国家基建下沉\"**：NSF 启动州与区域 AI 基础设施中心计划，科研计算社区进入 Gateways 2026 与新一轮培训周期。模型层出现一次明显的能力跳变，通用大模型在\"自主科学研究\"基准上从 20% 量级跨到 50%—65%。\n\n## 国内高校\n\n**上海大学：怎样建好、用好 AI 智慧平台。** 中国教育和科研计算机网（CERNET）刊发长文，系统披露上海大学\"千学百科\"AI 智慧平台的建设逻辑：以自建的\"自强5000\"超算中心为算力底座，采用 HPC 技术构建高性能算力集群与**异构算力管理平台**，配可扩展架构与智能资源调度以避免闲置、冲突和浪费；平台设\"千智汇聚\"\"学无止境\"\"百求必应\"\"科创未来\"四大模块，其中**\"科创未来\"面向科研与学习提供一站式大模型和算力开放能力**；同时建设通用大模型训推平台与大模型应用开发平台，提供兼容纳管多领域多厂商大模型的端到端开发工具链，并配套数据集、大模型库与实战教程。在底座之上已推出上海话大模型、类器官大模型、材料基因大模型及智能体等学科垂类模型。\n\n**南方科技大学图书馆：开通 LeapSpace AI 平台试用。** 试用期 2026 年 9 月 7 日至 10 月 6 日，首次使用需在校内 IP 范围完成个人账号注册。LeapSpace 是 Elsevier 面向研究者的科研级 AI 工作空间，基于出版商中立的内容底座，汇聚 **2000 万余篇全文同行评议文章与图书**、超过 1000 家内容伙伴（含 Emerald、IOP Publishing、NEJM Group、Sage），并调用 **1 亿余条 Scopus 学术记录**，覆盖 7000 多家出版商与 330 个学科；每个 AI 生成的回答都附带引用与原文链接，便于研究者溯源核验。对高校而言，这是图书馆以最低成本参与 AI4S 基础设施（可信语料 + 可溯源问答）的典型入口。\n\n**江苏省：全国首个省级 AI4S 公共算力中心揭牌。** 由省数据局、省发改委统筹指导，省教育厅、省科技厅、省财政厅、省卫健委、省国资委共同参与，省数据集团负责建设运营，面向全省高校、科研机构、公立医疗卫生机构和创新创业主体提供普惠、弹性、安全可信的专业化 AI4S 算力服务。目前落实约 **700P 规模化算力**，完成 **223 款算力产品定价上架**；依托省一体化算力监测调度平台实现多元异构算力（国产 + 先进异构）统一纳管、调度与服务；模型服务平台已接入 **70 余款模型并实现 API 调用**，后续集成通用模型库、高质量数据集与训推工具，做到工具、模型、算力\"开箱即用\"。安全侧实行算力专区化与物理隔离，配分级授权、全程审计、动态监测；运营思路为\"市场运营、公益兜底、开放共建\"。\n\n**浙江大学：启真算力中心细节披露。** 中国移动—浙江大学启真算力中心是全国首个校企合营模式算力中心，项目整体建成后浙江大学人工智能算力将达 **711Pflops**，达到全国高校头部水平；后续浙大算力网络将接入中国移动\"百川\"算力并网平台，实现算力资源统一调度与服务普惠。技术上基于移动云底座打造智算超算统一调度平台，整合高性能 CPU、GPU 与国产 AI 芯片，通过 1600Gbps 高速网络与九天人工智能平台开放，实现对通用、超算、智算算力的统一管理与调度，并打通数据、模型训练到推理验证的衔接。\n\n**上海交通大学：超级科研平台三模块。** 平台围绕智慧图书馆、AI for Science 计算中心、分析测试中心三大核心模块，集成全校各学科资源，实现算力、数据、仪器设备的共享与弹性调配，贯通\"从文献到计算再到实验\"的科研闭环。AI for Science 计算中心的异构算力支持\"一键开跑\"，调度系统把算力获取压缩至**分钟级**，本科生也可同时调用校内集群与云端超算完成传统需数月的分子模拟；分析测试中心在建的\"表征超级 OS\"可自动解析电镜、质谱数据并生成三维模型。试运行期间校内科研效率提升 30%、跨学科项目增长 40%。平台规划接入\"东数西算\"工程，成为国家算力网关键节点。\n\n**武汉理工大学材料学院：与腾讯云就 AI4S 建立常态化对接。** 腾讯云副总裁杨晖一行到访，围绕 AI for Science、人工智能赋能教育教学、智慧办公及科研算力交流研讨；双方一致同意发挥学校在材料科学、人工智能与工程应用方面的综合优势，以及腾讯云在云平台、大模型、算力资源和产业生态方面的技术优势，聚焦具体科研问题与实际应用场景，建立常态化沟通对接机制，形成一批具示范意义的合作成果。\n\n**华南农业大学：搭建校级 AI 算力平台。** 与联想合作，以搭载第五代英特尔至强处理器的联想问天 WA5480 G3 服务器为核心搭建新 AI 算力平台，专门解决数字信息与工程学院在数值计算、大模型训练等高并发场景的算力瓶颈。第五代至强芯片自带 AI 加速能力，无需额外加装加速硬件即可支撑两百亿参数大模型的推理调优，配 DDR5 内存与 PCIe 5.0 高速接口；部署后各类仿真与算法计算任务运行效率明显提升，多个课题组可同步开展科研，不必为算力排队。背景是 2026 年山东、郑州、江西等地密集出台算力补贴政策，支持高校加大算力投入。\n\n## 海外\n\n**NSF：启动国家和区域 AI 基础设施中心计划。** 2026 年 8 月 4 日正式宣布，目标是扩大 AI 驱动科学发现所需算力资源的可及性，并强化高校的研究、教育与劳动力培养。各中心需与 NAIRR 等国家层面计划对接，实现资源共享与协同，形成全国性 AI 科研基础设施网络；计划把**师资培训放在核心位置**。配套的网络研讨会第二场于 9 月 2 日举行，介绍技术与慈善组织对申请方的支持。\n\n**CaRCC：All Things AI 九月刊发布。** 校园科研计算联盟更新了 NAIRR 试点与其他 AI 计划的机会、活动与培训清单，包括 Gateways 2026（9 月 9—11 日，华盛顿特区）——科学网关与科研基础设施社区年会，聚焦拓宽计算资源获取的工具、平台与工作流，含教程、论文报告与动手实践环节。\n\n**arXiv：新一代科学计算生态工作坊报告。** 《Report of the 2026 Workshop on Next-Generation Ecosystems for Scientific Computing: Harnessing Community, Software, and AI for Cross-Disciplinary Team Science》（arXiv:2608.26519）于 8 月 27 日提交，作者覆盖美国国家实验室与高校的科研软件、算力与团队科学负责人，讨论社区、软件与 AI 如何在跨学科团队科学中协同。这是观察海外科研软件与算力生态治理的一手材料。\n\n**鄂维南：AI for Science 进入\"下半场\"。** 在 2026 AI for Science Congress（北京）上，中国科学院院士、北京科学智能研究院（AISI）学术委员会主任鄂维南表示，AI4S 正从\"构建 AI 驱动的科研工具\"转向\"重构整个科研生态\"：AI 的价值远不止加速研究，它将结构性地重塑基础研究的生产模式与运行体系。他把当前普遍把 AI 当作科研助手（文献检索、大规模仿真）视为第一阶段即\"科研生产力改善\"，真正的问题是\"AI for Science 之后\"——当技术能力跃升，科研的**组织方式、评价标准与资源配置**该如何系统性重新设计；并以通用软件生态为类比，设想一个整合算力、仿真引擎、领域知识库与自动化实验室的开放、通用科研基础设施。\n\n## 模型层：科学基准出现数量级跳变\n\n**Anthropic 发布 Claude Fable 5.1 / Mythos 5.1（9 月 2 日）。** 在衡量自主科学研究能力的 Terminal-Bench-Science 0.1 上得 52.6%，上代 Fable 5 为 24.7%、GPT-5.6 Sol 为 22.4%；Terminal-Bench 4.0 代码工程能力从 42.0% 升至 55.8%（Mythos 版 60.9%）；**缓存读取价格骤降 75%**，高强度 Agent 任务总成本最高可省 45%。Mythos 5.1 共用相同权重但开放更高风险能力上限，仅向通过 Cyber Verification Program 与 **Life Sciences Verification Program** 审核的机构开放。\n\n**OpenAI 发布 GPT-6 Astra（9 月 4 日）。** Terminal-Bench-Science 0.1 得 64.6%，完成同等任务的估计 API 成本比 Fable 5.1 低约 31%（低成本设置下仍得 61.1%）；Terminal-Bench 4.0 得 57.9%；FrontierMath Tier4 得 97.6%；ARC-AGI-3 得 99.9%（前代 7.8%）；OSWorld 2.0 得 72.6%，单项任务平均耗时从约 75 分钟缩短至 40 分钟。OpenAI 称模型已帮助解决数学领域长期存在的开放性问题，包括素数间隔研究中的两个新理论结果。定价为每百万输入 token 10 美元、输出 50 美元，另提供速度提升 2.5 倍的快速模式。\n\n**对高校 AI4S 平台的三点影响**：其一，缓存降价与 Prompt 缓存减免直接改善\"学校统一兜底 Token 成本\"模式的可持续性；其二，生命科学方向出现机构审核门槛（LSVP），会加强敏感学科的本地化部署与国产模型适配动力；其三，选型应从\"按 Token 定额\"转向\"按任务预算\"——单价上涨但单任务成本可能下降。\n\n## 本期观察：三个可跟进的信号\n\n1. **省级公共算力中心会不会成为省属院校的默认解**。江苏模式已经把\"算力产品定价上架 + 模型 API + 数据集 + 训推工具\"做成一站式供给，若其他省份跟进，自建校级集群的必要性会重新评估。\n2. **图书馆会不会成为\"可信科研 AI\"的采购主体**。南科大引入 LeapSpace 是一条低成本路径：不动算力、不建模型，先把\"带引用的科研问答\"提供给师生。\n3. **AI4S 的\"下半场\"讨论会不会落到考核改革**。鄂维南提出的组织方式、评价标准与资源重配，是比建平台更难、也更决定成败的一环；北大科学智能学院的实体建制与双导师制是目前少数的制度性答案。\n"}});

;(function(){
  var DB = window.__AI4S_API__ || {};
  function matchQ(item,q,fields){
    q=(q||'').trim().toLowerCase(); if(!q) return true;
    for(var i=0;i<fields.length;i++){var v=item[fields[i]];
      if(v && String(v).toLowerCase().indexOf(q)!==-1) return true;}
    return false;
  }
  function paginate(arr,limit,offset){
    offset=offset||0;
    if(limit==null||isNaN(limit)) return arr.slice(offset);
    return arr.slice(offset,offset+limit);
  }
  function toInt(v,def){ v=parseInt(v==null?'':v,10); return isNaN(v)?def:v; }
  function handleSignals(sp){
    var items=(DB.signals||[]).slice();
    var days=toInt(sp.get('days'),0);
    if(days>0){
      var mx=''; for(var i=0;i<items.length;i++){var d=items[i].occurred_on||''; if(d>mx)mx=d;}
      if(mx){var cut=new Date(mx+'T00:00:00Z'); cut.setUTCDate(cut.getUTCDate()-(days-1));
        var cutS=cut.toISOString().slice(0,10);
        items=items.filter(function(s){return (s.occurred_on||'')>=cutS;});}
    }
    var layer=sp.get('layer');
    if(layer&&layer!=='\u5168\u90e8') items=items.filter(function(s){return s.layer===layer;});
    var q=sp.get('q')||'';
    items=items.filter(function(s){return matchQ(s,q,['org','summary','source_title','region']);});
    return {items:paginate(items,toInt(sp.get('limit'),60),toInt(sp.get('offset'),0))};
  }
  function handleCases(sp){
    var items=(DB.cases||[]).slice();
    var country=sp.get('country');
    if(country&&country!=='\u5168\u90e8') items=items.filter(function(c){return c.country===country;});
    var layer=sp.get('layer');
    if(layer&&layer!=='\u5168\u90e8') items=items.filter(function(c){return c.layer===layer;});
    var q=sp.get('q')||'';
    items=items.filter(function(c){return matchQ(c,q,['org','org_en','platform','highlights','country','source_title']);});
    return {items:paginate(items,toInt(sp.get('limit'),200),toInt(sp.get('offset'),0))};
  }
  function handleArticles(sp){
    var items=(DB.articles||[]).slice();
    var kind=sp.get('kind');
    if(kind) items=items.filter(function(a){return a.kind===kind;});
    var q=sp.get('q')||'';
    items=items.filter(function(a){return matchQ(a,q,['title','dek']);});
    items=paginate(items,sp.has('limit')?toInt(sp.get('limit'),null):null,toInt(sp.get('offset'),0));
    if(sp.get('body')==='1') items=items.map(function(a){return DB.articleDetails[a.slug]||DB.articleDetails[String(a.id)]||a;});
    return {items:items};
  }
  function route(path,sp){
    if(path==='/api/facets') return {status:200,body:DB.facets};
    if(path==='/api/overview') return {status:200,body:DB.overview};
    if(path==='/api/signals') return {status:200,body:handleSignals(sp)};
    if(path==='/api/cases') return {status:200,body:handleCases(sp)};
    if(path==='/api/articles') return {status:200,body:handleArticles(sp)};
    var m=path.match(/^\/api\/articles\/(.+)$/);
    if(m){var d=DB.articleDetails[decodeURIComponent(m[1])];
      if(d) return {status:200,body:d};
      return {status:404,body:{error:'not found'}};}
    return null;
  }
  var origFetch=window.fetch.bind(window);
  window.fetch=function(input,init){
    var urlStr=(typeof input==='string')?input:(input&&input.url);
    try{
      var u=new URL(urlStr,window.location.href);
      if(u.origin===window.location.origin&&u.pathname.indexOf('/api/')===0){
        var r=route(u.pathname,u.searchParams);
        if(r) return Promise.resolve(new Response(JSON.stringify(r.body),
          {status:r.status,headers:{'content-type':'application/json'}}));
      }
    }catch(e){}
    return origFetch(input,init);
  };
})();
